export default [{"id":509,"question":"هناك مقالة للإمام أحمد بن حنبل يقول: من دعاك إلى غير التزوج فقد دعاك إلى غير الإسلام؟","title":"حكم من يدعو إلى عدم التزوج","answer":"الجواب: يعني دعاك إلى غير أحكام الإسلام؛ لأن حكم الإسلام التزوج.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6339/حكم-من-يدعو-الى-عدم-التزوج","audio":"https://files.zadapps.info/binbaz.org.sa/maram074.mp3","categories":["حكم الزواج وأهميته"]},{"id":511,"question":"ترك المرأة الزواج للدراسة والرجل مع القدرة هل يأثم ؟","title":"هل يأثم من يؤخّر الزواج مع القدرة؟","answer":"الجواب: ما ينبغي لا، إذا كان له شهوة الواجب البدار.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6341/هل-ياثم-من-يوخر-الزواج-مع-القدرة","audio":"https://files.zadapps.info/binbaz.org.sa/maram076 - 01 -  Start.mp3","categories":["حكم الزواج وأهميته"]},{"id":512,"question":"الزواج واجب؟","title":"متى يكون الزواج واجبًا في الشرع؟","answer":"الجواب: مع الشهوة والقدرة واجب.\n(دروس شرح بلوغ المرام، كتاب النكاح)","link":"https://binbaz.org.sa/fatwas/6342/متى-يكون-الزواج-واجبا-في-الشرع","audio":"https://files.zadapps.info/binbaz.org.sa/maram077 - 01 -  Start.mp3","categories":["حكم الزواج وأهميته"]},{"id":733,"question":"نصح الرسولُ الكريم ﷺ الشبابَ بالزواج، ولكن نلاحظ أنَّ الكثيرين من الفتيات يرفضن الزواج المُبكر بحججٍ واهيةٍ، فما توجيه سماحتكم في هذا الشأن؟ وما حكم الامتناع؟","title":"حكم التأخر عن الزواج وتسويفه","answer":"الجواب: ننصح الجميع من الذكور والإناث، الشباب والفتيات بالمبادرة إلى الزواج وترك التَّعللات التي لا وجهَ لها: لا بالدراسة، ولا بالوظيفة، ولا بغير ذلك، ننصح الجميع أن يُبادروا بالزواج، وأن يُخفِّفوا في المهور، وأن يدَعوا التَّكلفات في الولائم؛ حتى يتيسر الزواج، فمن العقبات: المبالغة في المهور، ومن العقبات: المبالغة في الولائم، ومن العقبات: زعمها أنها تريد التأخر حتى تنتهي من الدراسة.\nوهكذا الشباب: يقول: أنا أصبر حتى أنتهي من الجامعة، ثم إذا انتهى من الجامعة قال: أتوظف، ثم سوف أسعى في إيجاد فِلَّة أو إيجاد شقة، وهكذا تروح الأيام والليالي في التَّعللات، كل هذا لا ينبغي، ولا يجوز مع القدرة.\nيقول النبيُّ ﷺ: يا معشر الشباب، مَن استطاع منكم الباءة فليتزوج، فإنه أغضُّ للبصر، وأحصن للفرج، ومَن لم يستطع فعليه بالصوم، فإنه له وِجاء، وهذا أمرٌ، والأمر يقتضي الوجوب.\nوقال الله سبحانه: وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ [النور:32]، الأيامى: الذين ما عندهم أزواج من الرجال والنساء.\nفالزواج واجبٌ، ولا يجوز التأخير لمجرد التَّعللات بأنه يريد أن يشتري فِلَّةً، أو يعمر فِلَّةً، أو حتى يُنهي الدراسة، أو حتى تُنهي الدراسة هي، إذا كان قادرًا على الزواج فليُبادر، وعلى الفتاة أن تُوافق، وعلى أهلها أن يُوافقوا، ولا يجوز لهم التَّأخر مع القدرة على إنجاز الزواج؛ حرصًا على عفَّة الفروج، وغضِّ الأبصار، فإن الخطر عظيم، والزمان زمان مُخيفٌ، والفساد كبيرٌ، والاختلاط كثيرٌ، والشر متنوعٌ.\nفلا ينبغي للمؤمن أن يتساهل في هذا الأمر، بل ينبغي له أن يحرص على حفظ دينه، وحفظ سمعته، وحفظ جوارحه، وغضّ بصره، وإحصان فرجه بالزواج، ولا يقول بزواج واحدةٍ، حتى ولو باثنتين، ولو بثلاثٍ، ولو بأربعٍ، ولو ما رضيت بعض النساء عليه أن يتزوج، ويحرص على عفَّة فرجه، فإذا ما كفته واحدةٌ يأخذ ثنتين، وإذا ما كفته الثنتان يأخذ ثلاثًا، وإذا ما كفته الثلاث يأخذ أربعًا.\nولا ينبغي لها أن تأبى ذلك، ولا ينبغي لها أن تزعل من ذلك، ولا ينبغي لها أن تغترَّ بما قد يُذاع في بعض الإذاعات، أو بعض التلفاز، أو بعض الصحف: من إنكار التَّعدد، كل هذا باطلٌ، كله مخالفٌ لشريعة الله، والله أمر بالتَّعدد وأباحه وقال: فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ [النساء:3]، ربع زوجٍ خيرٌ من العدم، نصف زوجٍ خيرٌ من العدم، ثلث زوجٍ خيرٌ من العدم، خيرٌ من أن تبقى وحيدةً.\nفالواجب خوف الله، ومراقبة الله، والتَّحمل، والتَّصبر، وعدم التَّساهل في هذه الأمور، يجب البدار بالزواج، ويجب الحرص على العفَّة، وإذا اكتفى بواحدةٍ ورأى أنها تكفي فلا بأس، وإذا كانت عنده قوةٌ في حاجة النِّساء، ولا تعفّه الواحدة، وربما أفضى به هذا إلى الزنا؛ فليُبادر إلى الثانية والثالثة، لعلها تعفّه، والمرأة الواحدة يعتريها ما يعتري النساء من الحيض والنفاس والأمراض، فإذا كانت عنده ثانية استمتع بها وأعفته، وإذا كانت عنده ثالثة كذلك، والواجب عليها أن تعترف بهذا، وأن تُقرَّ بهذا، وأن تعذره في هذا الأمر إذا عدل فيها، واتَّقى الله فيها، وأدَّى حقَّها، والواجب عليه العدل وتقوى الله في ذلك.\nالمقصود من هذا كله الحثُّ على الزواج، والحرص على الزواج، وعدم التَّعلل، لا من الفتاة، ولا من الشباب، الواجب التَّسهيل في المهور والولائم، وعدم التَّكلف، وعدم التَّعلل بالتأخير إلى بعد الدراسة، أو إلى بعد كذا، أو كذا، لا، الإنسان من حين يبلغ الحُلُم فهو في حاجةٍ إلى الزواج، في حاجةٍ إلى عفَّة فرجه، إلى غضِّ بصره، إلى البُعد عن أسباب الفساد.\nالله يهدي الجميع، نسأل الله أن يهدي الجميع.","link":"https://binbaz.org.sa/fatwas/20609/حكم-التاخر-عن-الزواج-وتسويفه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0546حكم التأخرعن الزواج وحكم التعدد فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["حكم الزواج وأهميته"]},{"id":774,"question":"شابَّة تسأل تقول: أنا شابَّة عمري عشرون سنةً، وقد تقدَّم لي شابٌّ للزواج مني، ولكني اعتذرتُ بحجّة إكمال دراستي الجامعية، فما توجيهكم إليَّ في هذا؟","title":"بِم تُنْصح من ترفض الزواج لإكمال الدراسة؟","answer":"الجواب: أنا أنصح الشابَّ والفتاة أنا يُبادروا بالزواج، وقد قلتُ هذا غير مرةٍ، وفي مناسبات شتى، وفي \"نور على الدرب\"، لا ينبغي الاعتذار بالدراسة، ولا بتحصيل عمارة، ولا ببناء عمارة، ولا بتأثيث عمارة، ينبغي البدار بالزواج؛ حتى يغضَّ بصره، ويحصّن فرجه، رجلًا كان أو امرأةً، متى تيسر الزوج الصالح، والزوجة الصَّالحة المناسبة.\nفالذي ينبغي البدار، فإن تيسر إكمال الدراسة فالحمد لله، وإلا فلا يلزم، المطلوب من الدراسة الفهم والتَّفقه في الدين ومعرفة دين الإٍسلام، فإذا عرف دينَه فالحمد لله، ليس المقصود أن يكون موظَّفًا، أو يكون عالمًا كبيرًا، المقصود أن يتعلم دينه، ويتفقه في دينه، فإذا تعلَّم ما حصلت به معرفة دينه فالحمد لله، ولو خلي بعد ذلك لطلب الكسب والقيام على أهله.\nوهكذا المرأة إذا تيسر لها الزوج الصالح الذي ترغبه ينبغي لها أن تُوافق، ولو قطعت الدراسة في الجامعة، فكونها تتزوج وتُحصن فرجها وتحفظ دينها وتغضّ بصرها وتبتعد عن أسباب الفتنة هذا خيرٌ لها فيما نعتقد، ويدل على هذا قوله عليه الصلاة والسلام في الحديث الصحيح: يا معشر الشباب، مَن استطاع منكم الباءة فليتزوج، فإنَّ الأمر قال بعضُ أهل العلم: إنه للسنة والتأكيد، وقال آخرون: إنه للوجوب، ما دام الرجلُ عنده شهوة والمرأة عندها شهوة فهو للوجوب، وهذا أظهر، وهذا هو الأصوب في الأوامر؛ أنها للوجوب، قال: فليتزوّج؛ فإنه أغضُّ للبصر، وأحصن للفرج، ومَن لم يستطع فعليه بالصوم؛ فإنه له وجاء، هذا الأمر يُوجب المبادرة والمسارعة مع القدرة إلى الزواج.\nوأنا أنصح أن يُبادر ولو بالاستدانة، ولو بالقرض، ولو بشراء حاجةٍ إلى أجلٍ ثم يبيعها ويتزوج، فالزواج له شأنٌ، وله فائدةٌ عظيمةٌ ومصالح جمَّة.","link":"https://binbaz.org.sa/fatwas/20692/بم-تنصح-من-ترفض-الزواج-لاكمال-الدراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0589نصيحة لمن ترفض الزواج بحجة أكمال الدراسة الجامعية ابن باز فتاوى المحاضرات.mp3","categories":["حكم الزواج وأهميته"]},{"id":1201,"question":"أنا فتاة ملتزمة، ولا أريد أن أتزوج، فماذا عليَّ أن أفعل؟ أو هل عليَّ ذنبٌ في ذلك؟ أفيدونا جزاكم الله خيرًا.","title":"حكم من ترفض الزواج وحكم غلاء المهور","answer":"الجواب:\nتزوَّجي، لا، ما يصلح، ما يجوز البقاء، تزوَّجي، ولو أنَّك مُلتزمة تزوَّجي، إذا جاء الكُفْءُ تزوَّجي، يقول الله جلَّ وعلا: وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ [النور:32]، الأيامى: التي ما لها زوج، والرجل الذي ما له زوج يُقال له: أيم، الرجل أيم، والمرأة أيمة أيضًا، التي ما لها زوج يُقال لها: أيم وأيمة، وكذا الرجل الذي ما له زوجة -ولو كان قد تزوَّج سابقًا- يُقال له: أيم، الله أمر بإنكاحهم.\nعليكِ بالزواج إذا جاء الكفء، لا تجلسي بدون زوجٍ أبدًا، يقول النبيُّ ﷺ: إذا خطب إليكم مَن ترضون دينَه وخُلقه فزوِّجه، إلا تفعلوه تكن فتنةٌ في الأرض وفسادٌ كبيرٌ، ويقول النبيُّ ﷺ: يا معشر الشباب هذا يعمُّ الرجال والنساء، مَن استطاع منكم الباءَة فليتزوّج، فإنه أغضُّ للبصر، وأحصنُ للفرج، ومَن لم يستطع فعليه بالصوم؛ فإنه له وجاء.\nالواجب الزواج على الرجل والمرأة جميعًا إذا جاء الكُفْءُ، إذا يسَّر الله الكفء لا تمنعوه، أجيبوا ولا تتعنَّتوا، ولا تتكلَّفوا في المهور، ولا في الولائم، خففوا في المهور، يكفي المهر القليل، النبي قال لبعض الناس: التمس ولو خاتمًا من حديدٍ يزوّج به، ولو خاتمًا من حديدٍ وزوَّجه على أن يُعلِّمها بعض القرآن، لا تتكلَّفوا في المهور، زوِّجوا بالمئة وبالألف والألفين، على ما يسَّر الله، لا تتكلَّفوا، ولا في الولائم، النبي قال لعبدالرحمن بن عوف: أولم ولو بشاةٍ، ما هو بلزوم التَّكلف، الشاة تكفي، والشاتان تكفيان، ولا حاجة إلى التَّكلف، لا تتشددوا في المهور حتى يتيسر الزواج، عليكم بالتَّساهل في المهور، وفي الحُلي، وفي كل شيءٍ، خفِّفوا على الأزواج، على الخُطَّاب؛ حتى يرغبوا، حتى يتزوَّجوا، على أبيها يُخفف، على أمِّها، وعلى أخواتها، لا يُشجِّعوها على التَّكلف.\nالواجب على الأخوات والأمهات والجدَّات وزوجات الآباء وعلى الأقارب التَّشجيع على التَّخفيف، شجِّعوا على تخفيف المهور والولائم، رغِّبوا الناس في الزواج، شجِّعوهم على الزواج حتى يكثر الزواجُ، حتى تقلّ العانسات في البيوت، وحتى يقلّ الشباب الذين ما حصَّلوا زوجة، شجِّعوا الناس، شجِّعوهم على الزواج، خفِّفوا المهور، يسِّروا المهور، لا تتكلَّفوا في الولائم، حتى لا تبقى بنتٌ، ولا يبقى شبابٌ إلا متزوج.\nهذا يجب فيه التَّعاون بين الأخيار: على الأم أن تُعين، والأب أن يُعين، والأخ أن يُعين، بعض الناس يُطالب في بنته كأنها سلعة يبيعها بمئة ألفٍ أو بمئةٍ وخمسين ألفًا -نعوذ بالله- .. اطلب الميسور من الطيب، ولو عشرة آلاف، ولو خمسة آلاف، ولو ألفين، إذا رضيت البنت والحمد لله، ولو مئة ريـال، بعض السلف زوَّج على درهمين، وثلاثة دراهم، خفِّفوا في المهور.\nعليكَ يا أباها بالتَّشجيع على التَّخفيف، بعض النساء آباؤهن -نعوذ بالله- عقبة كؤود في الزواج، ما يزوج إلا بتعبٍ، يخليها في غنمه، أو في بيته تخدم، ولا يُزوّج إلا بمئة ألفٍ، أو مئة وخمسين ألفًا مع التَّعب، هذا ظلمٌ عظيمٌ، داخلٌ في الظلم -نعوذ بالله- يجب الحذر، زوِّجْها بما تيسر إذا جاء الكُفْءُ، زوِّج واتَّقِ الله، ولا تحبسها، ولا تطلب المهر الطويل الذي يشقُّ على الناس، إذا جاء الكفء فهو النِّعمة، الكفء هو الرغبة، هو المهر، إذا جاء الكفء الطيب هو النعمة العظيمة، ولو بريالٍ واحدٍ، الله يهدي الجميع.","link":"https://binbaz.org.sa/fatwas/21268/حكم-من-ترفض-الزواج-وحكم-غلاء-المهور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1126أنا فتاة ملتزمة ولا أرعب بالزواج فهل عليَّ أثم؟ ابن باز فتاوى.mp3","categories":["حكم الزواج وأهميته"]},{"id":1691,"question":"رجلٌ اعتاد صيامَ الاثنين والخميس، فإذا دُعِيَ يوم الاثنين يعني: وعده شخصٌ وقال له: يوم الاثنين - إن شاء الله - تتغدَّى عندي، فهل الأفضل أن يقول له: أنا اعتدتُ الصيامَ أو يفطر؟","title":"حكم مَن دُعِي لوليمة في يومٍ اعتاد صومه","answer":"الجواب:\nلا، يُجيب الدعوةَ ولا يأكل، يُجيب الدعوةَ، ويعتذر عن الطعام، وإن أفطر فلا بأس، فالنبي ﷺ قال: إذا دُعِيَ أحدُكم فليُجِبْ: فإن كان صائمًا فليدعو، وإن كان مُفْطِرًا فليطعم، إن كان صائمًا يدعو لهم ويقول: سامحوني أنا صائم، وجزاكم الله خيرًا، فيذهب إليهم، ويدعو لهم، وإن أفطر فلا بأس.\nس: مُخَيَّرٌ بين الاثنين؟\nج: نعم مُخَيَّرٌ، وإن كان جبرُهم بالفطر أفضل.\nس: يعني: يكون أميرَ نفسه؟\nج: نعم، لكن يُجيبهم، ويذهب إليهم، ثم يعتذر، أو يُفْطِر، ويأكل معهم.\nس: هل الأفضل أن يعتذر لهم؟\nج: إذا كان يَجْبُرُهم بذلك، ويرى أنَّ المصلحة في إفطاره جَبْرًا لخواطرهم أفطر، وإن لم يكن يضرُّهم، ولا يهمُّهم؛ أفطر أو ما أفطر فيعتذر، يقول: سامحوني أنا صائم، وجئتُ وأجبتُ الدَّعوة، وسامحوني في أن أرجع.","link":"https://binbaz.org.sa/fatwas/21797/حكم-من-دعي-لوليمة-في-يوم-اعتاد-صومه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/من كانت له عادة صيام ودعي لوليمة يوم صيامه هل يجيب أم يعتذر.mp3","categories":["صيام التطوع","حكم الزواج وأهميته","الآداب والأخلاق المحمودة"]},{"id":3639,"question":"قول الله تعالى وَتَبَتَّلْ إِلَيْهِ تَبْتِيلًا..؟","title":"حكم ترك العمل والزواج للانشغال بالعبادة","answer":"الجواب: يعني للعبادة، يعني يعبده جل وعلا ويجتهد في عبادته، ما هو معناه يترك العمل.\nس: من قال بأن الإنسان إذا اشتغل بعبادة الله وبر والديه أفضل من أن يتزوج؟\nالشيخ: يُردُّ عليه ويُبين له أن هذا جهل، الله أمر بالنكاح، قال: وَأَنْكِحُوا [النور:32] وقال: فَانْكِحُوا مَا طَابَ لَكُمْ [النساء:3] والرسول ﷺ أمر بذلك، ولا يعلو كلام أحد مع كلام الله ورسوله، الكلام الذي يخالف كلام الله ورسوله يلزم رده.\nس: تسمية مريم بالبتول؟\nالشيخ: للعبادة يعني.","link":"https://binbaz.org.sa/fatwas/23824/حكم-ترك-العمل-والزواج-للانشغال-بالعبادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاشتغال بالعبادة والتبتل وترك العمل والنكاح.mp3","categories":["حكم الزواج وأهميته"]},{"id":3653,"question":"حديث التزويج قبل التسع هل عليه دليل صريح؟","title":"حكم تزويج الفتاة قبل بلوغها التسع؟","answer":"الجواب: قصة عائشة، زواج عائشة من النبي ﷺ، هذا هو الأصل في هذا.\nس: إذا توفي الأب ورأى الجد مصلحة في تزويجها وهي أقل من تسع؟\nالشيخ: لا، لا يزوجها إلا بإذنها بعدما تبلغ تسعًا فأكثر هذا خاص بالأب وقوفًا مع النص؛ لأصل العموم. والبكر يستأذنها أبوها، هذا هو الأصل، يُستثنى منه قصة عائشة فقط.","link":"https://binbaz.org.sa/fatwas/23841/حكم-تزويج-الفتاة-قبل-بلوغها-التسع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الدليل على التزويج قبل التسع.mp3","categories":["حكم الزواج وأهميته"]},{"id":3712,"question":"الزواج بنية الطلاق؟","title":"ما حكم الزواج بنية الطلاق؟","answer":"الجواب: عند الجمهور لا بأس، وتركه أوْلى، الأكثرون يقولون لا بأس، هذا شيء بينه وبين ربه، وذهب الأوزاعي وجماعة إلى منعه، والأوْلى تركه، الأوْلى عدم النية، هذا هو الأولى والأحوط.\nس: بعض الناس يسافرون إلى بعض البلاد يسافرون بهذه النية ؟\nالشيخ: ولو، تركُ هذه النية أوْلى، تركها أحوط؛ خروجًا من الخلاف.\nس: فعلهم صحيح؟\nالشيخ: الجمهور يرون جواز هذا، والأحوط تركه.","link":"https://binbaz.org.sa/fatwas/23903/ما-حكم-الزواج-بنية-الطلاق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الزواج بنية الطلاق.mp3","categories":["حكم الزواج وأهميته"]},{"id":5846,"question":"يقول: لا حياء في الدين، أنا شاب أريد أن أتزوج، ولكن أريد أن أعرف كيف أباشر زوجتي طبق ما فعله الرسول ﷺ؟ وما الذي أرتديه من الملابس؟ وهل أبتعد عنها إذا كانت حاملًا وشكرًا؟","title":"كيفية النكاح الشرعي","answer":"الجواب: الزواج معروف، يتزوج، يعني يخطب المرأة، يسأل عن دينها، وعن حالها، وإذا عرف أنها صالحة له مسلمة، أو رآها يتزوج الزواج الشرعي، يقوم وليها يعقد له عند بعض طلبة العلم الذين يعرفون؛ حتى يبينون له ما ينبغي، ويقول: زوجتك، والزوج يقول: قبلت بحضرة شاهدين عدلين، أربعة: الولي، والزوج، وشاهدان، ويقول الولي: زوجتك، ويقول: قبلت على مال بينهما معروف على حسب ما تيسر.  وإذا دخل عليها ذكر بعض أهل العلم أنه يصلي ركعتين أفضل، فإذا صلى ركعتين؛ حسن، يدعو الله -جل وعلا- أن يوفق بينهما، وإذا لمسها يسأل الله خيرها، وخير ما جبلت عليه، ويتعوذ بالله من شرها، وشر ما جبلت عليه، ثم إذا شاء الاتصال بها اتصل بها.  وإذا كانت حبلى، فالنكاح باطل، إذا كان دخل عليها، وهي حبلى؛ فهذا نكاح باطل، أما إذا حملت منه هو؛ فلا بأس أن يطأها وهي حامل، ولكن لا يطأها وهي حائض، ولا نفساء، الحائض، والنفساء لا توطأ، أما الحامل؛ فلا بأس أن يطأها وهي حامل إذا كان حملها منه، أما إذا كان دخل عليها، ووجدها حاملًا، فهذه لها عدة من غيره، وهو نكاح باطل، نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/1193/كيفية-النكاح-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_189.mp3","categories":["صيام التطوع","حكم الزواج وأهميته","الآداب والأخلاق المحمودة"]},{"id":5935,"question":"ما حكم مؤخر الصداق؟ وهل نصف دينه بالزواج، ويتقي الله بالنصف الآخر، من أين هذا القول؟","title":"ما صحة القول بأن الزواج شطر الدين","answer":"الجواب: يروى عن النبي ﷺ في حديث في سنده نظر إذا تزوج الإنسان؛ فقد أحرز شطر دينه؛ فليتق الله في الشطر الآخر جاء هذا من طرق لا تخلو من ضعف عند أهل العلم، ولا شك أن الزواج مهم، ولكن كونه الشطر محل نظر! إنما هو مهم، الله يقول -جل وعلا-: وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32].  ويقول : وَإِنْ خِفْتُمْ أَلَّا تُقْسِطُوا فِي الْيَتَامَى فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ الآية [النساء:3] والرسول ﷺ أمر بالنكاح -كما سمعتم- وحث الشباب على ذلك، وقال: تزوجوا الودود الولود؛ فإني مكاثر بكم الأمم يوم القيامة فالرسول ﷺ حث على هذا، ورغب فيه كما أمر به الله  لكن كونه شطر الدين هذا محل نظر؛ لضعف الحديث. ولكن ينبغي للمؤمن أن يحرص عليه، وهو شعبة من الدين، وفرض من الفرائض، ومن أسباب العفة، وغض البصر، ومن أسباب الاستقامة، ومن أسباب صلاح المجتمع، ومن أسباب كثرة النسل، وكثرة الأمة، وكثرة من يعبد الله  فينبغي الجد في ذلك، ولكن ينبغي له أن يختار المرأة الصالحة. وإن تيسر أنه ينظر للمرأة قبل الزواج؛ فهو أحسن، النبي ﷺ أمر الخاطب أن ينظر أخبر ﷺ إذا خطب أحدكم امرأة، فإن استطاع أن ينظر إلى ما يدعوه إلى نكاحها؛ فليفعل. وسأله رجل قال: يا رسول الله، إني خطبت فلانة، فقال: أنظرت إليها؟ قال: لا، قال: اذهب فانظر إليها فإذا تيسر النظر إليها؛ فهو أولى، وينبغي لأهلها أن يسمحوا بذلك، تنظره، وينظرها، لا بأس. لكن في محل ما فيه خلوة، ينظر إليها، وتنظر إليه مع حضور والدها، أو أمها، أو أخيها، يعني ليس في خلوة في مكان ما فيه خلوة، لا يخلو بها؛ لأن الخلوة من أسباب وقوع الفاحشة. وكذلك ما نبه عليه الشيخ صالح ما قد يقع من بعض الناس، أنا ما سمعته من المسلمين، لكن موجود في الخارج، وهو أن يسافر معها، ولم يعقد عليها؛ حتى ينظر إليها، وتنظر إليه، فهذا من البلاء العظيم، والمنكر الفظيع، نعوذ بالله، إنما مجرد نظر ينظر إليها، وتنظر إليه فقط، أما أن يخلو بها، ويسافر معها، وتسافر معه؛ فهذا منكر كبير، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1286/ما-صحة-القول-بان-الزواج-شطر-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_273.mp3","categories":["صيام التطوع","حكم الزواج وأهميته","الآداب والأخلاق المحمودة"]},{"id":6170,"question":"تزوجت عند عمي، وشرط علي مائة ألف ريال، فماذا أفعل؟ أأترك الزواج، أم ماذا؟","title":"حكم الاستدانة لأجل الزواج","answer":"الجواب: سمعت الكلام يا أخي، إذا شرط العم مائة ألف ريال إذا تيسر لك تحصيل المائة ولو بالقرض، ولو بالدين؛ فافعل، استدن، أو اقترض، واستعن بالله، وإن لم يتيسر لك؛ فلا تكلف نفسك لاَ يُكَلِّفُ اللّهُ نَفْساً إِلاَّ وُسْعَهَا [البقرة:286] فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وإذا مات يوفي الله عنه. يقول النبي ﷺ: من أخذ أموال الناس يريد أداءها؛ أدى الله عنه فمن يأخذ الأموال بالقرض، أو بالدين، ونيته الوفاء، يريد الزواج، والعفاف، أو يريد إقامة سكن له، أو ما أشبه ذلك من المصالح؛ فلا حرج عليه، والله يوفي عنه .","link":"https://binbaz.org.sa/fatwas/1634/حكم-الاستدانة-لاجل-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_525.mp3","categories":["حكم الزواج وأهميته","الحكم على الأحاديث"]},{"id":6173,"question":"تزوجت عند عمي، وشرط علي مائة ألف ريال، فماذا أفعل؟ أأترك الزواج، أم ماذا؟","title":"حكم الاستدانة لأجل الزواج","answer":"الجواب: سمعت الكلام يا أخي، إذا شرط العم مائة ألف ريال إذا تيسر لك تحصيل المائة ولو بالقرض، ولو بالدين؛ فافعل، استدن، أو اقترض، واستعن بالله، وإن لم يتيسر لك؛ فلا تكلف نفسك لاَ يُكَلِّفُ اللّهُ نَفْساً إِلاَّ وُسْعَهَا [البقرة:286] فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] وإذا مات يوفي الله عنه. يقول النبي ﷺ: من أخذ أموال الناس يريد أداءها؛ أدى الله عنه فمن يأخذ الأموال بالقرض، أو بالدين، ونيته الوفاء، يريد الزواج، والعفاف، أو يريد إقامة سكن له، أو ما أشبه ذلك من المصالح؛ فلا حرج عليه، والله يوفي عنه .","link":"https://binbaz.org.sa/fatwas/1634/حكم-الاستدانة-لاجل-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_525.mp3","categories":["حكم الزواج وأهميته","الحكم على الأحاديث"]},{"id":6189,"question":"قال ﷺ: يا معشر الشباب، من استطاع منكم الباءة؛ فليتزوج.. إلى آخر الحديث، هل الصوم المطلوب متتابع، أم متقطع؟","title":"كيفية صوم من لا يستطيع النكاح","answer":"الجواب: الرسول ﷺ قال: يا معشر الشباب، من استطاع منكم الباءة؛ فليتزوج يعني استطاع مؤنة الزواج؛ فليتزوج، فإنه أغض للبصر، وأحصن للفرج، حث على النكاح، وعلى الآباء أن يسارعوا في تزويج أبنائهم، وبناتهم، وأن لا يردوا الكفء إذا خطب، وإن تعاونوا على ذلك في تسهيل المهور، وتسهيل الولائم، وعدم التكلف في هذه الأمور حتى يسهلوا لأبنائهم، ولبناتهم، ما شرع الله من الزواج. أمّا إذا عجز، ولم يستطع؛ فعليه بالصوم -كما قاله النبي ﷺ، والاستعفاف، وقد أمر الله بذلك. والصوم يكون متتابعًا، ويكون أيضًا متفرقًا، لا بأس على حسب حاله، وقدرته إذا صام متتابعًا حسن، حتى يكف بهذا شر الشهوة، وإذا صام متفرقًا؛ فلا بأس، الأمر في هذا إليه فهو أعلم بحاله، والصوم مستحب، ومشروع من أجل تخفيف شر الشهوة، وإذا تعاطى بعض الأدوية التي تخفف من ذلك فهو حسن أيضًا. ومن أعظم الدواء: غض البصر، والبعد عن التجول في الأسواق بلا حاجة، والنظر إلى النساء في الأسواق، أو في بيته إذا كان لديه غير محارمه؛ فينبغي له في مثل هذا الحذر، والبعد عن إطلاق البصر، فإن هذا من أعظم الأسباب لسلامته، أما إطلاق البصر، وتجوله في الأسواق بغير حاجة بين النساء، فهذا من أعظم الأسباب في الفتنة، وإطلاق الشهوة، ووقوع الفاحشة، نسأل الله العافية.","link":"https://binbaz.org.sa/fatwas/1665/كيفية-صوم-من-لا-يستطيع-النكاح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_544.mp3","categories":["حكم الزواج وأهميته"]},{"id":6361,"question":"هل ورد التزوج بين الإنس، والجن؟","title":"حكم الزواج من الجن أو تزويجهم","answer":"الجواب: ما ورد، ما نعرف في هذا شيئًا، وهذا فيه خلاف بين أهل العلم؛ لأنه لا يعلم، لا يمكن التحقق من إسلامهم، ولا دينهم.. فلا ينبغي التزوج منهم بالكلية؛ لأننا لا نستطيع أن نعرف الحقيقة، وهل دعواه الإسلام صحيحة، أو غير صحيحة، فهو على خطر.","link":"https://binbaz.org.sa/fatwas/1911/حكم-الزواج-من-الجن-او-تزويجهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_695.mp3","categories":["حكم الزواج وأهميته","الحكم على الأحاديث"]},{"id":6409,"question":"كثير من الشباب -إلا ما شاء الله- كثيري السفر خارج البلاد، وأنتم تعلمون ما يقعون فيه من الزنا، وشرب الخمر، فإذا تقدم أحد من هؤلاء الشباب للزواج، هل نزوجهم بعد أن لوحظ عليهم الصلاح، والله يقول: الزَّانِي لَا يَنْكِحُ إِلَّا زَانِيَةً أَوْ مُشْرِكَةً [النور:3]؟","title":"حكم نكاح من يخاف وقوعه في الزنا","answer":"الجواب: ليس كل شباب ذهب إلى الخارج يكون فاسدًا، قد يكون بعض الشباب من أصلح الناس، وهو في الخارج، وقد يكوِّن من الجمعيات، والعمل الصالح، والدعوة إلى الله ما تقر به العيون، وقد يكون أصلح من حاله في بلاده، لكن الأكثر يفسد ويتغير .. من سافر إلى الخارج، إلى إنجلترا، أو إلى فرنسا، أو إلى أمريكا؛ تتغير حاله إلى فساد، وهذا هو الأغلب عليهم في دينهم، وأخلاقهم -نسأل الله العافية- فإذا لم يظهر منه فساد؛ فإنه يزوَّج، أو كان فسادًا، ثم تاب، وظهرت عليه أمارات التوبة؛ يزوَّج، التوبة تَجُبُّ ما قبلها، والحمد لله.","link":"https://binbaz.org.sa/fatwas/2115/حكم-نكاح-من-يخاف-وقوعه-في-الزنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_767.mp3","categories":["حكم الزواج وأهميته","الحكم على الأحاديث"]},{"id":6568,"question":"هل يطيع الشاب والديه إذا أمره بتأخير الزواج حتى يصبح عمره خمسة وعشرين عامًا، أو عشرين، أو حتى ينال الشهادة، وهو راغب في الزواج قبل ذلك؟ ما حكم من ليس له رغبة في الزواج؟","title":"حكم طاعة الوالدين إذا أمرا بتأخير الزواج","answer":"الجواب: أولًا: ليس لوالديه أن يقولا له هذا الكلام، ليس لوالديه أن يأمراه بالتأخير، ولا يجوز لهما أن يأمراه بالتأخير وهما يقدران على تزويجه. ثانيًا: ليس له أن يطيعهما في تأخير الزواج، وهو يرغب في الزواج، ويستطيع الزواج؛ لأن الرسول  قال: إنما الطاعة في المعروف وقال: لا طاعة لمخلوق في معصية الخالق.  فإذا أمره أبواه بالزنا، أو بالخمر؛ لا يجوز، فهكذا إذا أمراه أن يؤخر الزواج وهو يستطيع الزواج، أو يستطيعان أن يزوجانه؛ يلزمهما أن يزوجانه، ولا يجوز لهما أن يؤخرا الزواج حتى يكمل الدراسة الجامعية، أو حتى كذا وكذا ما دام يشتهي النكاح، ويريد النساء، فالخطر قائم، الخطر قائم والواجب إبعاده عن الخطر بتزويجه، هذه أسباب، والله الموفق  لكن هذه أسباب؛ فلا يجوز لهما تأخير الزواج، ولا يجوز له طاعتهما في هذا الشيء إذا استطاع أن يتخلص من هذا الأمر.","link":"https://binbaz.org.sa/fatwas/2431/حكم-طاعة-الوالدين-اذا-امرا-بتاخير-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_958.mp3","categories":["حكم الزواج وأهميته","بر الوالدين"]},{"id":6673,"question":"شاب أراد أن يتزوج، ولكن والدته أظهرت له أنها لا ترغب زواجه من تلك المرأة، دون ذكر السبب إلى الكراهية، ثم تكرر هذا من الوالدة مرة ثانية عندما خطب امرأة أخرى، فما هو العمل، علمًا أن الشاب لم يتزوج بعد؟","title":"حكم الزواج بامرأة بخلاف رغبة الأم","answer":"الجواب: عليه أن يحاول مع والدته بيان محاسن المرأة التي تدعو إلى الزواج بها، وبيان حاجته إلى الزواج، وأن يستعين على ذلك بأبيه، أو إخوته، أو غيرهم ممن لهم صلة بوالدته من أخوال، ونحو ذلك؛ حتى ترضى -إن شاء الله- بالزواج، وحتى توافق على المرأة المعينة، ولا يتساهل في هذا شيئًا، بل يجتهد في إقناعها بالأسباب البينة، ويستعين على هذا بمن تقدره والدته من أخوال، أو أعمام، أو أبيه، أو جده، أو غير ذلك من الأقارب، والجيران وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2] وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4]. فإنها إذا لم تقنع فما ذاك إلا بأسباب منه هو، أو بسيئة منه، فقد قال الله : وَمَا أَصَابَكُمْ مِنْ مُصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُو عَنْ كَثِيرٍ[الشورى:30] فليفتش، ولينظر في نفسه، وليتب إلى الله من سيئاته، وتقصيره، وليسأل ربه أن يشرح صدرها لما يريد من الخير، وأن يهديها لقبول ما أراد، هذا كله إذا كانت المخطوبة طيبة في دينها سليمة. أما إذا كانت الوالدة تعرف عنها ما لا ينبغي، وقد نصحت له في منعها من ذلك؛ لأنها تعرفها، وأنها لا تصلح في دينها، أو لأسباب وجيهة؛ فالوالدة تطاع في هذا الأمر، ولا ينبغي لك أن تجد في نفسك عليها؛ لأنها ناصحة، فالوالدة لا تزال ناصحة أبدًا إلا ما شاء الله، وهو قليل، والغالب، على الوالد والوالدة النصيحة، ومحبة الخير للولد، والحرص على ما ينفعه في الدنيا، والآخرة. فاتهم رأيك، وحاسب نفسك، واعلم أن الوالد، أو الوالدة، أو غيرهما إنما يكون منهما ما يعوق عن بعض شأنك؛ لأسباب منك، أو بتقصير منك، أو بجهل منك، فإذا تواصى فيك الاستقامة، والنصح، ومحبة الخير، وأن المخطوبة طيبة، وسليمة، فسوف يهدي الله الوالد، والوالدة لذلك، فعليك بدعاء الله، وأن يهديك صراطه المستقيم، وأن يشرح صدر والديك لما فيه سعادتك، ولما فيه نجاتك، وأبشر بالخير، وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مِنْ أَمْرِهِ يُسْرًا [الطلاق:4].","link":"https://binbaz.org.sa/fatwas/2558/حكم-الزواج-بامراة-بخلاف-رغبة-الام","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1053.mp3","categories":["حكم الزواج وأهميته","بر الوالدين"]},{"id":6717,"question":"أيهما أفضل الزواج، أم عدمه، مع العلم أن عددًا من كبار العلماء كانوا عزابًا، كالطبري شيخ المفسرين، أو ابن تيمية إمام أهل السنة، والعقيدة، والمجاهد في سبيل الله، وغيرهما، ثم أبناء علماء الشيعة يتبعون آباءهم في العلم كما هو ملموس، بخلاف أبناء علماء السنة، وأعني في القرن الأخير، والسلام عليكم ورحمة الله وبركاته؟","title":"أهمية الزواج وحكمه والرد على من يرغبون عنه","answer":"الجواب: ما كان في أمر الزواج هو السنة، ولا كلام في أن الواجب على المؤمنين أن يعتنوا بالزواج، ولا يتركوه، وإن تركه بعض الناس لأسباب، قد يكون تركها؛ لأنه ما فيه شهوة، قد يكون شغل عنه، قد يكون لأسباب ما علمناها، أما الرسول ﷺ فقد حث على الزواج، وقبل ذلك في كتاب الله، قال الله -جل وعلا-: فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ [النساء:3] وقال وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ [النور:32]. فالزواج أمر مطلوب لا بد منه، فهو واجب في الجملة، والنبي  قال: يا معشر الشباب من استطاع منكم الباءة؛ فليتزوج، فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع؛ فعليه بالصوم، فإنه له وجاء وقال: تزوجوا الولود الودود؛ فإني مكاثر بكم الأمم يوم القيامة. فالمقصود: أنه ﷺ حث على الزواج ،كما حث عليه كتاب الله  فالقول بأن الزواج يترك، أو يشرع تركه، أو كذا، هذا منكر من القول، ولو فعل ذلك بعض الناس، إن صح أن ابن جرير ما تزوج، أو صح أن شيخ الإسلام لم يتزوج، قد يكون لهما أعذار، لكن ليسوا حجة في هذا الأمر، والرسول ﷺ قد بين هذا الأمر، شيء قد بينه الرسول، وبينه الله ليس لأحد كلام في مخالفة ذلك كائنًا من كان، بل يجب أن يؤخذ بقول الله، ورسوله، ولو تركه كثير من الناس، فلا عبرة بتركهم؛ لأنهم قد يكونون معذورين، وأيضًا ليسوا حجة فيما يخالف شرع الله. السؤال: الأمر للوجوب، أم على التخيير؟ الجواب: للوجوب على الصحيح، وقال بعض أهل العلم: يجب عند خوف الفاحشة إذا اشتدت به الشهوة، ولكن الأصل هو للوجوب مطلقًا إذا قدر؛ لأنه إذا قدر يحصن فرجه بذلك، ويتباعد عن أسباب الشر.","link":"https://binbaz.org.sa/fatwas/2599/اهمية-الزواج-وحكمه-والرد-على-من-يرغبون-عنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1095.mp3","categories":["حكم الزواج وأهميته","الحكم على الأحاديث"]},{"id":6780,"question":"نسمع بعض الشباب يقولون -هداهم الله-: نتزوج بعد الدراسة، وعلى الأصح بعد الكلية، فما رأيكم في هذا، وأيضًا في شروط الكلية العسكرية يكون غير متزوج، هل هذا جائز في الإسلام؛ علمًا بأن بعض العلماء لم يتزوجوا؟","title":"الحث على المبادرة بالزواج وترك الأعذار الواهية","answer":"الجواب: هذا تقدم الكلام فيه، وأن الدراسة ليست عذرًا، بل الواجب التزوج متى تيسرت أسبابه؛ لأنه واجب، الصحيح أنه واجب؛ لقول النبي ﷺ: يا معشر الشباب من استطاع منكم الباءة؛ فليتزوج هذا أمر، والأمر للوجوب، هذا هو الأصل، حتى يأتي صارف، فالواجب على من قدر أن يتزوج، وألا يعتذر بالدراسة، ولا بغير الدراسة، الواجب البدار مهما قدر لا من الرجال، ولا من النساء؛ لأن هذا أغض للبصر، وأحصن للفرج، كما قاله النبي -عليه الصلاة والسلام- ولأمره -جل وعلا- في قوله: وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ [النور:32] الأمر للأمة، الأمر لأولياء الأمور، ولأولياء الرجال، والنساء أن يتعاونوا في هذا، في إنكاح الأيامى، وعدم تركهم، فالواجب العناية بهذا الأمر، وعدم الاعتذار بالدراسة، لا من الشباب الذكور، ولا من الإناث.  فالواجب في هذا التعاون على إيجاد النكاح، والبدار بالنكاح، والدراسة لا تمنع من ذلك، إن استمروا فالحمد لله، وإذا لم يستمروا؛ فلا مانع، وسوف يجدون أعمالًا أخرى غير الدراسة يعملون فيها ، إما حرة، وإما غير حرة، والرزق عند الله  وبعضهم يأتيه الشيطان، ويقول له: إنك إذا تأخرت عن الدراسة، وتأخرت فلانة عن الدراسة؛ قد يأتيها يوم تحتاج للوظيفة، ما عندها وظيفة، ما عندها عمل، تبقى فقيرة، كثير منهم الآن ما يرغب في الدراسة للعلم، ليعرف أمر الله، وحكم الله، لا، حريص عليها لأجل الوظيفة، هذا الغالب على الناس، كأنه سيموت فقرًا إذا لم يتوظف، الرزق عند الله  ما هو بالوظيفة، قد يأتي على الناس أيام ما في وظائف.  فالمقصود: أن هذا ظن سيئ، والحرص على الوظيفة من طريق الدراسة، لا على أن يعرف أمر الله، ودين الله، وأصل التعلم أن يتفقه الإنسان في دين الله، وأن يعرف أحكام الله؛ حتى يعبد الله على بصيرة، وهكذا المرأة، أما الوظائف فشيء آخر، أمر ثانوي، فيه مصلحة للمسلمين، وتعاون لا شك، لكن لا ينبغي أن يقدم هذا الظن السيئ على  طاعة الله، ورسوله، بل يبادر بالنكاح، وأمر الدراسة متيسر بعد ذلك، وإن لم يتيسر؛ أمكن أن يعمل الإنسان أعمالًت حرة، أو بما ما منعه من الدراسة الأولىـ ولو كانت ناقصة، ولا ينبغي له أن يعطل ما أوجب الله عليه من أجل استكمال الدراسة بزعمه إلى أن ينتهي من الجامعة، أو الدكتوراه، أو الماجستير، وهكذا المرأة، الدرب واحد، الطريق واحد.","link":"https://binbaz.org.sa/fatwas/2637/الحث-على-المبادرة-بالزواج-وترك-الاعذار-الواهية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1133.mp3","categories":["حكم الزواج وأهميته","الحكم على الأحاديث"]},{"id":6960,"question":"من استطاع الباءة، وله أسرة كبيرة: والداه، وثمانية أخوات، وثلاثة إخوان لم يتزوج أي منهم، وحالتهم وسط -والحمد لله- ويحتاجون له إن أراد الله لإحداهن الزواج، فهل ينتظرهن، أو يتزوج، كما أن الرسول ﷺ قال: \"اطلبوا الغنى في النكاح\"؟","title":"المبادرة بالزواج سبيل إلى الغنى","answer":"الجواب: لا، لا ينتظرهم، إذا تيسر أمره؛ يتزوج، ما عليه يتزوجـ ولو قبل أخيه الكبير، ولو قبل أخته الكبيرة، لا ينتظرهم، متى يسر الله الزواج؛ فليبادر بالزواج، وهذا يقوله الله في كتابه العظيم يقول الله سبحانه: وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32]. السؤال: صحة الحديث؟ الجواب: ليس بحديث لا، هذا قوله -جل وعلا-: وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ[النور:32]. السؤال: أقول الحديث الذي ذكره يا شيخ: «اطلبوا الغنى في النكاح»؟ الجواب: أقول ما أعلم له أصلًا، لكن فيه معنى آخر، يقول الرسول -عليه الصلاة والسلام-: ثلاثة حق على الله عونهم، وذكر منهم المتزوج يريد العفاف، يعان، يعينه الله، ويسهل الله أمره.","link":"https://binbaz.org.sa/fatwas/2890/المبادرة-بالزواج-سبيل-الى-الغنى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1337.mp3","categories":["حكم الزواج وأهميته","الحكم على الأحاديث"]},{"id":7119,"question":"شابة تريد الصيام الاثنين والخميس، لكن والدتها تمنعها عن الصيام بحجة أنها في السن صغيرة، فماذا تفعل؟ هل تطيع والدتها مع قدرتها على الصوم؟","title":"حكم تقديم صيام التطوع على طاعة الوالدة","answer":"الجواب:\n\nنعم نعم، صوم النافلة مستحب، وطاعة الوالدة واجبة، والوالدة قصدها الخير، وقصدها أن ترحم حالها، ولا تشق على نفسها، لكن ينبغي لها أن تعالج الموضوع بالحكمة، والكلام الطيب، والأسلوب الحسن؛ حتى تسمح أمها بالصيام إذا كان الصوم لا يشق عليها ولا يؤثر عليها.\n\nفالمقصود: أن هذا من الوالدة من باب العطف والرحمة، فلا ينبغي للبنت أن تعصيها، ويكون بينها وبينها الشر، ولكن تعالج الموضوع بالكلام الطيب، والأسلوب الحسن مع الوالدة؛ حتى ترضى -إن شاء الله- وحتى تمكن من صوم بلا مشقة.","link":"https://binbaz.org.sa/fatwas/3152/حكم-تقديم-صيام-التطوع-على-طاعة-الوالدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1510.mp3","categories":["صيام التطوع","حكم الزواج وأهميته","الآداب والأخلاق المحمودة"]},{"id":7312,"question":"نحن في قرية نتزوج ونحن صغار، ومن يتزوج أحيانًا يكون عمره أربعة عشر، أو ثلاثة عشر سنة، فهل هذا يجوز؟","title":"حكم الزواج في سن مبكرة","answer":"الجواب: لا بأس إذا تيسر لكم الزواج، لا بأس. السؤال: لكن متى يكون بلوغ الرجل؟ الجواب: بلوغه بأحد ثلاثة أمور: إما بإكمال خمسة عشرة سنة، أو بالإنزال عن شهوة عن احتلام، أو غير احتلام، أو بإنبات الشعر -الشعرة التي حول الفرج- الشعر الخشن المعروف، فإذا حصل هذه الثلاث، أو واحدة منها؛ صار بالغًا رجلًا، والمرأة مثله، وتزيد أمرًا رابعًا، وهو الحيض، إذا حاضت؛ صارت بالغة أيضًا، مع هذه الثلاثة الأمور، نعم.","link":"https://binbaz.org.sa/fatwas/3387/حكم-الزواج-في-سن-مبكرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1703.mp3","categories":["حكم الزواج وأهميته","الحكم على الأحاديث"]},{"id":7472,"question":"أيضاً هذا سؤال من الحائر كما قال (ي. و. ف) تتعلق بهذه المشكلة أو هذه الظاهرة الاجتماعية، يقول: أنا شاب في العشرين من عمري أريد أن أكمل نصف ديني ولكن لا أستطيع الباءة، فما هي نصيحتكم لي والحالة هذه؟","title":"نصيحة للشباب غير القادرين على الزواج","answer":"الجواب:  ثبت عن رسول الله عليه الصلاة والسلام أنه قال: يا معشر الشباب! من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر وأحصن للفرج، فمن لم يستطع فعليه بالصوم فإنه له وجاء فالرسول أرشد عليه الصلاة والسلام إلى الصوم (من عجز عن الباءة) يعني: عن المئونة للنكاح، فإن عليه أن يصوم ويستعين بالصوم على إمساك الشهوة وتخفيضها، والسلامة من شرها مهما أمكن، فالصوم بإذن الله يحصل به الوجاء يعني: الخصاء، يعني: يحصل به إضعاف الشهوة، ويحصل به كفها عن الشدة.\nفالحاصل: أن الصوم فيه علاج للشهوة وفيه علاج لطموح الإنسان إلى النكاح، ومن أسباب غض البصر، ومن أسباب ضعف سلطان الشيطان، فإنه يجري من ابن آدم مجرى الدم، والصوم يضعف ذلك. فالحاصل: أن الصوم يضعف هذه النزعة وهذا الميول إلى الجنس، فيحصل به يعني شيء كبير من المقصود، وإن تعاطى شيء من الأدوية التي تضعف الشهوة ولا تقطعها، إذا تعاطى شيء من الأدوية التي يحصل بها يعني إضعاف الشهوة وتخفيف الشهوة لكن لا يقطع الشهوة بل تبقى الشهوة عند الحاجة، هذا لا بأس أيضاً، قد يكون علاج أيضاً. نعم.","link":"https://binbaz.org.sa/fatwas/4315/نصيحة-للشباب-غير-القادرين-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_003/00302.mp3","categories":["حكم الزواج وأهميته"]},{"id":8291,"question":"نعرض لها سؤال في نهاية هذه الحلقة ونبقي بقية أسئلتها إلى حلقة قادمة إن شاء الله، تقول: إن والدي أو والداي يرغبان في زواجي، لكني في الحقيقة لم أفكر في هذا الموضوع أصلاً ولا أريد أن أتزوج للأبد، فإني أرفض طلبهما وأنا خائفة من الله سبحانه وتعالى؛ حيث في الآية -كما تقول- (سخط الله من سخط الوالدين) فهل هذا يعتبر نوع من عقوق الوالدين؟ وماذا أعمل؟","title":"حكم الزواج لمن قدر عليه من الرجال والنساء","answer":"الجواب: ليست هذه آية: (سخط الله في سخط الوالدين)، وإنما هذا حديث عن النبي ﷺ عن ابن عمر عن النبي ﷺأنه قال: رضا الله في رضا الوالدين وسخط الله في سخط الوالدين فليس هذا من القرآن، بل هذا من حديث الرسول ﷺ، عن عبد الله بن عمرو عن النبي ﷺ، فالمقصود أن هذا ليس من القرآن ولكنه من الحديث، فالواجب عليك أن تنظري في الأمر فإن الزواج فيه مصالح كثيرة، وهو سبب للعفة لغض البصر وحفظ الفرج، ومن أسباب تكثير الأمة ووجود النسل، فينبغي لك أن تنظري في الأمر ولا تتركي الزواج، بل عليك أن تطيعي أبويك في ذلك فقد نصحا لك، والنبي ﷺ يقول: يا معشر الشباب! من استطاع منكم الباءة فليتزوج؛ فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء وهذا يعم البنين والبنات، فكما يجب على الابن التزوج إذا تيسر له ذلك فهكذا البنت يجب عليها ذلك، إذا تيسر لها الزوج المناسب.\nواختلف العلماء في هذا: هل يجب وجوباً أو يستحب ويتأكد، أو فيه تفصيل: إن خاف الزنا وإلا فلا، على أقوال لأهل العلم، والأظهر أنه يجب متى تيسر الأمر وجب؛ لأن الرسول أمر بهذا عليه الصلاة والسلام قال: ( فليتزوج ) والأصل في الأمر للوجوب، هذا هو الأصل، ولأن طبيعة الإنسان وفطرته تدعوه إلى ذلك، وفي ترك الزواج خطر كبير على الذكر والأنثى جميعاً، فربما وقع كل منهما في الفاحشة بسبب ذلك، وربما أطلق بصره بسبب ذلك، فالواجب هو التزوج مع القدرة على الزواج، إذا كان له شهوة في النكاح، وكانت لها شهوة في الرجال فالواجب لهما الزواج، اللهم إلا أن يكون هناك مانع يمنع من ذلك، لعدم وجود ما يستطيع به جماع المرأة؛ لأنه ليس له أرب في النساء، أو فيها هي مانع من عيب يمنع من الزواج هذا شيء آخر. المقصود أنه ما دام الرجل سليماً والفتاة سليمة فالواجب الزواج مع القدرة؛ لما فيه من المصالح العظيمة التي منها: غض بصر الجميع، ومنها: حفظ الفرج، ومنها: تكثير نسل الأمة الذي أخبر النبي ﷺ أنه يباهي بها الأمم يوم القيامة، ومنها: مصالح أخرى في إيجاد الزواج، فلا ينبغي للبنت ولا للابن ترك ذلك، بل ينبغي الحرص عليه عند القدرة. نعم.","link":"https://binbaz.org.sa/fatwas/6104/حكم-الزواج-لمن-قدر-عليه-من-الرجال-والنساء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_107/10707.mp3","categories":["حكم الزواج وأهميته"]},{"id":8910,"question":"أمامي رسالة سماحة الشيخ بعث بها أحد الإخوة المستمعين يقول: منصور صالح من الرياض، أخونا رسالته مطولة ملخصها: أنه شاب في الثانية والعشرين من عمره يشكو قلة ذات اليد، ويشكو أيضاً من عنت العزوبة، ويرجو من سماحة الشيخ التوجيه الشرعي في هذه الناحية؟","title":"الواجب على من لم يستطع الزواج لقلة ذات اليد","answer":"الجواب: لا ريب أن الزواج من أهم المهمات ومن أفضل القربات لقول النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج فإنه أغض للبصر وأحصن للفرج، والله يقول سبحانه: وَأَنكِحُوا الأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32]، في الحديث الصحيح يقول الرسول ﷺ: ثلاثة حق على الله عونهم- ذكر منهم-: المتزوج يريد العفاف.\nالمقدم: الأول لو سمحت؟\nالشيخ: المتزوج يريد العفاف يعني: يقصد العفاف فالله يعينه سبحانه وتعالى.\nفنصيحتي لهذا الشاب السائل أن يفعل الأسباب التي يستطيعها حتى يتزوج، إما بقرض وإما بالاستدانة يشتري شيئاً إلى أجل معلوم ويبيعه والله يوفي عنه ويتزوج؛ لقول النبي ﷺ: من أخذ أموال الناس يريد أداءها أدى الله عنه.\nوالنبي ﷺ قد استدان وهو أفضل الخلق استدان، ومات وعليه دين عليه الصلاة والسلام فلا بأس بالاستدانة ولا حرج في الاستدانة إما من طريق القرض أو من طريق أن يشتري حاجات كسيارة أو غيرها إلى أجل معلوم ثم يبيعها بنقد ويتزوج ولا بأس بذلك، وهنا لدينا مشروع ولكنه مطول مشروع مساعدة للمتزوجين، وهذا له شروط خمسة:\nالأول منها: أن يكون سعودياً وهكذا الزوجة المخطوبة.\nالثاني: أن يكون عاجز بالبينة مثبتاً من المحكمة أنه عاجز عن النفقة عن الزواج يعني عن المهر.\nالثالث: أن يتم العقد بينه وبين أهل المرأة ولكن يبقى الدخول.\nالرابع: أن يكون هذا أول زواج، أو قد تزوج لكن ماتت زوجته، أما المطلق لا ما عندنا له مساعدة.\nالخامس: أن يثبت أنه محافظ على الصلاة في الجماعة من أهل المعرفة به في مسجده.\nفإذا تمت الشروط يساعد بخمسة وعشرين ألف على حساب المحسنين، هذه أمور من أهل الخير، من زكوات أهل الخير ومساعداتهم، خمسة وعشرون ألف إذا تمت هذه الشروط الخمسة، يساعد بها لكنها قد تتأخر؛ لأن الناس كثيرون ينتظرون الآن، قد يبلغون الألوف والمال ليس بالكثير الذي يأتي لهذا المشروع، فلهذا قد يتأخر خمسة أشهر.. ستة أشهر.. ما يأتيه الدور أو أكثر من ذلك.\nالمقدم: بسيطة.\nالشيخ: نعم.\nالمقدم: ستة أشهر ليست بشيء.\nالشيخ: فإذا رأى أن يتقدم لهذا المشروع ويوفي بهذه الشروط فلا بأس، لعل الله أن يسهل له أمره، وإن استدان أو اقترض حتى يكون أعجل فهذا خير إن شاء الله، وله البشرى بأن الله سيسهل أمره وأن يقضي عنه دينه؛ لأن الزواج عمل صالح فيه عفة الفرج وغض البصر والتسبب لعفة امرأة أيضاً وغض بصرها وحفظ فرجها، والتسبب أيضاً لوجود الولد وتكثير الأمة ففيه مصالح. نعم.\nالمقدم: بارك الله فيكم، لعل كثيراً من المحسنين يودون الإسهام في هذا المشروع الخيري إلا أن الإعلان عنه بطيء أو أن العنوان غير معروف أو كذا، لعله من المناسب أن يتفضل سماحة الشيخ فيذكر بهذا؟\nالشيخ: أنا أهيب بإخواني المسلمين في المملكة وغيرها أن يساعدوا في هذا المشروع من الزكاة وغيرها، وقد كتبنا عن ذلك مرات كثيرة، والغالب أنا نكتب أيضاً في آخر شعبان لأن كثيراً من الناس إنما يخرج الزكاة في رمضان.\nفالحاصل أنا كتبنا عن هذا مرات كثيرة وسنكتب إن شاء الله هذه الأيام أيضاً وعند دخول رمضان أيضاً إن شاء الله، لكن أهيب بمن يسمع هذه الكلمة، أهيب بهم أن يساهموا في هذا المشروع؛ لأن فيه إعانة لكثير من الشباب على الزواج وهم عاجزون، فأنا أهيب بجميع إخواني الذين يسمعون هذه الكلمة أن يساهموا في هذا المشروع إما من الزكاة وإما من غيرها والله يأجرهم ويثيبهم سبحانه.\nالمقدم: اللهم آمين. من الزكاة جائز أيضاً؟\nنعم.. نعم؛ لأن ما نعطي إلا أهل الحاجة، ما نساعد إلا أهل الحاجة لثبوت ذلك عند المحكمة.\nالمقدم: فهم فقراء ..\nالشيخ: نعم، فهم فقراء مستحقون.\nالمقدم: بارك الله فيكم، لعله من المناسب أن تتفضلوا بذكر العنوان سماحة الشيخ لمن يريد أن يرسل بتبرعه إلى هذا المشروع؟\nالشيخ: العنوان دار الإفتاء باسمي عبد العزيز بن عبد الله بن باز دار الإفتاء- الرياض.","link":"https://binbaz.org.sa/fatwas/7066/الواجب-على-من-لم-يستطع-الزواج-لقلة-ذات-اليد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_141/14105.mp3","categories":["حكم الزواج وأهميته"]},{"id":9276,"question":"هل زواج الابن واجب على الأب أم لا؟","title":"حكم تزويج الأب الغني ابنه","answer":"","link":"https://binbaz.org.sa/fatwas/7439/حكم-تزويج-الاب-الغني-ابنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_154/15409.mp3","categories":["النفقات","حكم الزواج وأهميته"]},{"id":9728,"question":"سماحة الشيخ! هذه رسالة وصلت من السائلة (ش. ص) الرياض تقول: تذكر يا سماحة الشيخ بأنها فتاة اقتربت من الثلاثين ومتخرجة من الجامعة منذ فترة طويلة، ووالدها رافض فكرة الزواج طمعًا في الوظيفة التي تقول: لم أستطع الحصول عليها منذ زمن، وتقول: بأنني ألجأ إلى الله  أدعوه بأن يرزقني الزوج الصالح، وإنني أدعو الله بعد كل صلاة وخاصةً في الثلث الأخير من الليل، والذي زادني أسى ولوعة هو أن الله  لم يستجب لدعائي ولم يحقق لي الأمنية التي تتمناها كل فتاة، تقول تذكر: وإنني أفكر دائماً بأنني قد أدعو بشيء لم يكتبه الله  لي من الأساس، فهل هذا التفكير جائز؟ وفي آخر رسالتي أتوجه أن تدعو لي يا سماحة الشيخ مأجورين؟","title":"نصيحة لفتاة تأخر زواجها وحث الآباء على تزويج البنات","answer":"الجواب: يسر الله أمرك، ورزقك الزوج الصالح، ونوصيك بسؤال الله جل وعلا أن يمنحك الزوج الصالح في السجود، وفي آخر التحيات، وفي آخر الليل، اسألي الله جل وعلا ولا تقنطي ولا تيئسي، اسألي الله أن الله يمنحك ... الزوج الصالح، وأن يعينك على حق الزوجية، وأبشري بالخير إن شاء الله أبشري بالخير. والواجب على أبيك أن يساعد في هذا، الواجب على أبيك أن يتقي الله وأن يلتمس لك الزوج الصالح، وأن لا يشغله حب المال عن تزويجك، بل يجب أن يجتهد في تزويجك وسوف يغنيه الله عن وظيفتك وعن راتبك، وأنت لا تقنطي ولا تيئسي، قد يكون عدم الإجابة بأسباب معاصيك، قد يكون لك معاصي فعلتيها، فاتق الله وتوبي إلى الله وحاسبي نفسك، فقد تمنع الإجابة بأسباب المعصية، قد تكوني تساهلت في الفرائض في الصلوات الفريضة، قد تكوني تساهلت ببر والديك، قد تكوني تساهلت في غير ذلك من المعاصي فاتق الله حاسبي نفسك جاهديها، وتوبي إلى الله من تقصيرك في المعاصي، وأبشري بالخير سوف يجيب الله دعوتك، وسوف يرزقك الزوج الصالح إذا صدقت وأخلصت في الدعاء وتجنبت أسباب الحرمان من المعاصي والسيئات. نعم.\nالمقدم: هل من نصيحة للآباء سماحة الشيخ؟\nالشيخ: الواجب على الآباء أن يتقوا الله، نعم ننصح الآباء جميعاً والأجداد وجميع الأولياء ننصحهم أن يتقوا الله وأن يزوجوا مولياتهم، وأن لا يمنعوا ذلك من أجل الدراهم والدنانير، الواجب عليهم أن يزوجوهن حرصاً على عفتهن وعلى سلامتهن، نسأل الله للجميع الهداية والتوفيق. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/7883/نصيحة-لفتاة-تاخر-زواجها-وحث-الاباء-على-تزويج-البنات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_272/27218.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات"]},{"id":9998,"question":"تسأل وتقول: بعض الآباء إذا تقدم لبناتهم خاطب لا يزوجونه، بحجة أن الفتاة لا تزال صغيرة، أو لأنها لا تحسن أعمال المنزل، فهل من كلمة إلى مثل هؤلاء الآباء؟","title":"ضرورة مبادرة الآباء بتزويج الأبناء والبنات","answer":"الجواب: نعم، وصيتي للآباء ولجميع الأولياء من إخوة وبني إخوة وأعمام نوصي الجميع بأن يتقوا الله في مولياتهم من البنات والأخوات وبنات الأخ وبنات العم، نوصي الجميع بأن يتقوا الله فيهن وأن يحرصوا على تزويجهن متى جاء الخاطب الكفء، ولو كانت غير متعلمة تتعلم عند زوجها ما دامت أهلاً للزواج وتتحمل الزواج بنت خمسة عشر بنت ستة عشر بنت سبعة عشر فأكثر، تتحمل الزواج تقوى على الزواج، فالواجب أن يجاب الخاطب بمشورتها ورضاها، تستشار وإذا سكتت وهي بكر كفى ذلك، النبي عليه السلام قال: إذنها سكوتها.\nأما إن كانت ثيبا -يعني: قد تزوجت- فلابد من الإذن، اللفظ تقول: نعم لا بأس.\nوالواجب على الولي أن يتقي الله وأن يحرص على تزويج الفتاة فإن جلوسها بدون زوج فيه خطر عليها، فلا يجوز التساهل في هذا الأمر، والواجب على الآباء أيضاً الحرص على تزويج الأبناء إذا قدروا على ذلك، لأن جلوس الولد بغير زواج فيه خطر عظيم، فالواجب على الأب أن يزوجه وأن يجتهد في تزويجه ولو تساهل الولد يلزمه بالزواج يجاهده حتى يتزوج حتى يسلم من الفتنة لأن الزواج من رحمة الله وبفضله من أسباب السلامة، يقول النبي ﷺ في الحديث الصحيح: يا معشر الشباب! من استطاع منكم الباءة فليتزوج -يعني: المئونة- فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء فأمر ﷺ الشباب بالزواج وقال: إنه أغض للبصر وأحصن للفرج، وهذا يعم الفتاة والذكر، يعم الشباب من الذكور والإناث.\nفالواجب على الآباء وغيرهم أن يعتنوا بتزويج بنيهم وإخوتهم إذا تأهلوا للزواج وقدروا على تزويجهم من أموالهم أو من أموال المزوجين، بحيث لا يتساهلون بهذا، إن كان ابنه غنياً جاهده حتى يتزوج، وإن كان فقيراً زوَّجه من ماله إذا كان الولي غنياً، وهكذا البنت إذا خطبها الكفء زوجها وإذا تيسر يخطب لها هو يلتمس، هذا طيب كونه يلتمس هو من الشباب الطيبين يقول: يا فلان! أنا عندي بنت أحب أن أزوجك إياها، أو عندي أخت فإذا وافق الحمد لله، عمر وهو أفضل الخلق بعد النبي ﷺ وبعد الصديق عمر أفضل الخلق بعد نبي الله بعد الأنبياء وبعد الصديق خطب لبنته حفصة لما خرجت من عدة زوجها الذي مات عنها عرضها على عثمان وعرضها على الصديق لفضلهما، فـعثمان اعتذر والصديق سكت لأنه علم أن النبي ﷺ له رغبة فيها، فتزوجها النبي ﷺ، وهي حفصة ، فكون الإنسان يخطب لابنته أو لأخته ليس فيه نقص بل هو مشكور ومأجور إذا التمس لها الزوج الصالح، فإذا جاء الزوج الصالح وخطب فالواجب البدار إلى إجابته ولا يؤخر ذلك، لأن البنت كذا أو لأنه فقير أو وظيفته ما هي بكبيرة لا، الرزق عند الله الرزق عند الله، جاء في الحديث عن النبي ﷺ أنه قال: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه إلا تفعلوه تكن فتنة في الأرض وفساد كبير.\nولا سيما في عصرنا هذا عصر الفتن وعصر الانحراف، فالواجب الحذر من التساهل والواجب البدار بتزويج البنين والبنات إذا خطب البنات الأكفاء وتيسر الكفء ولو أن تخطب أنت لها، ولو أن تلتمس لها أنت، وهكذا بنوك وإخوتك وبنو أخيك تحرص على تزويجهم بالكلام والمشورة والنصيحة، وبالمال إذا كانوا فقراء حسب طاقتك، يقول النبي ﷺ: من كان في حاجة أخيه كان الله في حاجته متفق على صحته.\nحديث عظيم يقول ﷺ: من كان في حاجة أخيه كان الله في حاجته فإذا كنت في حاجة أخيك في الزواج أو أختك أو بنتك فأنت على خير عظيم، أو أخيك أو ابن أخيك، ويقول جل وعلا: وَتَعَاوَنُوا عَلَى الْبِرِّ وَالتَّقْوَى [المائدة:2] فالتعاون على الزواج من التعاون على البر والتقوى، نسأل الله للجميع التوفيق والهداية.\nالمقدم: اللهم آمين جزاكم الله خير.","link":"https://binbaz.org.sa/fatwas/8168/ضرورة-مبادرة-الاباء-بتزويج-الابناء-والبنات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_300/30006.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات"]},{"id":10766,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية العربية السورية، وباعثها مستمع من هناك رمز إلى اسمه بالحروف (ع. ب. س) يقول: أنا شاب أبلغ من العمر ثمانية عشر عاماً طالب في المدرسة ثالث ثانوي، ولي والدة تبلغ من العمر حوالي ثمانية وخمسين عاما، والدي متوفى منذ خمسة عشر عاماً، وأريد والدتي أن تذهب إلى الحج ولكنها تقول: إن ذلك لا يجوز وهو حرام حتى تتزوج، أرجو من سماحتكم إفادتي، إذ والدتي تفضل تزويجي قبل أدائها للحج، وجهونا حول هذا الموضوع جزاكم الله خيراً.","title":"حكم تقديم الحج على الزواج والعكس","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه، ومن اهتدى بهداه.\nأما بعد: فلا شك أن الحج فرض على كل إنسان استطاع السبيل إليه؛ لقول الله : وَلِلَّهِ عَلَى النَّاسِ حِجُّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا [آل عمران:97]، فإذا كنت تستطيع الحج من جهة المال وجب عليك الحج، وإذا كانت تستطيع الحج هي من جهة المال وجب الحج، وإن بدأت بالزواج؛ لأنك بحاجة إلى الزواج فلا حرج؛ لأن الزواج أيضاً فرض مع الشهوة والرغبة فيه، لقول النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج؛ فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء.\nوبكل حال: لا بأس أن تقدم الحج على الزواج وقول أمك: إنه حرام غلط منها، عفا الله عنا وعنها، لا بأس بالحج بل عليك أن تحج إذا استطعت الحج، ولك أن تقدم الزواج إذا كنت ترغب في الزواج، وتخشى على نفسك من مضرة التأخير وخطر التأخير، وهي كذلك إذا كان المراد حجها هي فإنها تحج أيضاً ولو قبل زواجه، إذا كانت تستطيع الحج أو أنت تستطيع الحج حتى تحججها من مالك، فإنها لا حرج عليها أن تحج قبل أن تتزوج هي وقبل أن تتزوج أنت، حتى ولو حجت وهي أيم ما تزوجت كذلك، أو أنت إذا كان قصدها أنت لا بأس أن تحج هي قبل أن تتزوج أنت.\nفالمقصود أن الكلام هذا ليس في محله غلط، فلك أن تتزوج أنت ولها أن تتزوج هي ولا حرج في ذلك، أما تأجيل الحج حتى تتزوج أنت أو حتى تتزوج هي هذا لا أصل له، بل هذا جائز وهذا جائز، وإذا كانت تستطيع الحج ولم تحج هي فعليها أن تحج بعد خروجها من العدة إذا كانت ... مع أن أباك قد مات من مدة طويلة عليها أن تحج إذا كانت تستطيع الحج، وأنت عليك أن تحج إذا استطعت الحج ولو قبل الزواج، وإذا أردت أن تقدم الزواج فلا حرج في ذلك، الأمر في هذا واسع؛ لأن هذا واجب وهذا واجب، مع الشهوة إذا كنت تشتهي النكاح وتخشى على نفسك، فإن قدمت النكاح فلا بأس وإن قدمت الحج فلا بأس، وعليك أن تقنعها وتوجهها إلى الخير وتعلمها بما سمعت الآن، ولعلها تسمع أيضاً هذا البرنامج وتستفيد في هذا الباب وترجع عن قولها. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرا، مفهوم الرسالة كما فهمت سماحة الشيخ! أن الوالدة هي التي تمتنع عن الحج حتى يتزوج ابنها؟\nالشيخ: كله لا وجه له، سواءً كان المراد هي أو المراد الولد، على كل حال لها أن تحج هي وإن لم يتزوج ولدها، وله أن يحج قبل الزواج، وليس شرطاً أن يقدم الزواج، لكن إذا احتاج إلى الزواج وخاف على نفسه وقدم الزواج فلا حرج. نعم.\nالمقدم: جزاكم الله خيراً، لعلها تريد توفير النفقة لزواج ابنها؟\nالشيخ: قد يكون هذا لكن لا يجوز أن ..... حرام، لا تقل: حرام، لو قالت يعني: نحب أن نزوجك وينبغي أن نبدأ بك ... من باب يعني تقديم الزواج على الحج هذا لا بأس إذا دعت الحاجة إلى ذلك. نعم.\nالمقدم: لكن لا تقل: حرام.\nالشيخ: نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8941/حكم-تقديم-الحج-على-الزواج-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_348/34801.mp3","categories":["حكم الحج والعمرة","حكم الزواج وأهميته"]},{"id":10833,"question":"هل يأثم الوالدان إذا لم يعطيا ابنهما المال لكي يتزوج، بحجة أنه يجب عليه أن يكمل الدراسة الجامعية، ثم يعمل ويحصل على الأموال من عمله لكي ينفقها على زوجته؟","title":"حكم تزويج الوالدين لولدهما","answer":"الجواب:  إذا كان الوالدان يستطيعان أن يزوجاه وجب عليهما تزويجه، ولا يجوز تأخير ذلك إلى أن يكمل الدراسة؛ لأنه معرض للفتنة، فالواجب على والديه إعفافه وإعانته على الخير، إذا كانا قادرين أو أحدهما، فأما إذا كانا عاجزين فليس عليهما حرج فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. أما إذا كان أبوه غنيًا يستطيع تزويجه، أو أمه كذلك، فإن الواجب عليهما تزويجه وعدم تأخير ذلك إذا طلب ذلك، بل يجب أن يحرصا على ذلك، ليصوناه عما حرم الله، وليجتهدا في سلامته، فكما يجب عليهما أن ينفقا عليه ما يسد حاجته ويستر عورته فالإنفاق عليه فيما يبعده عن الحرام ويسبب غض بصره وحفظ فرجه أهم من ذلك. نعم والله المستعان. المقدم: جزاكم الله خيرًا، الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9018/حكم-تزويج-الوالدين-لولدهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_355/35511.mp3","categories":["النفقات","حكم الزواج وأهميته"]},{"id":10839,"question":"هل يأثم الوالدان إذا لم يعطيا ابنهما المال لكي يتزوج، بحجة أنه يجب عليه أن يكمل الدراسة الجامعية، ثم يعمل ويحصل على الأموال من عمله لكي ينفقها على زوجته؟","title":"حكم تزويج الوالدين لولدهما","answer":"الجواب:  إذا كان الوالدان يستطيعان أن يزوجاه وجب عليهما تزويجه، ولا يجوز تأخير ذلك إلى أن يكمل الدراسة؛ لأنه معرض للفتنة، فالواجب على والديه إعفافه وإعانته على الخير، إذا كانا قادرين أو أحدهما، فأما إذا كانا عاجزين فليس عليهما حرج فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. أما إذا كان أبوه غنيًا يستطيع تزويجه، أو أمه كذلك، فإن الواجب عليهما تزويجه وعدم تأخير ذلك إذا طلب ذلك، بل يجب أن يحرصا على ذلك، ليصوناه عما حرم الله، وليجتهدا في سلامته، فكما يجب عليهما أن ينفقا عليه ما يسد حاجته ويستر عورته فالإنفاق عليه فيما يبعده عن الحرام ويسبب غض بصره وحفظ فرجه أهم من ذلك. نعم والله المستعان. المقدم: جزاكم الله خيرًا، الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9018/حكم-تزويج-الوالدين-لولدهما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_355/35511.mp3","categories":["النفقات","حكم الزواج وأهميته"]},{"id":10994,"question":"رسالة جاءت من الموصل في العراق، وباعثها أحد الإخوة من هناك يقول: إنني المسلم (ن. ش. ح) يقول: إني شاب في السابعة والعشرين من عمري أريد أن أتزوج، ولا أطيق ذلك؛ لأننا في بلدنا يطلبون علينا المهر وهو خمسة إلى عشرة آلاف دينار، وأنا لا أملك سوى راتبي الذي لا يكفي إلا لعيشي أنا وعائلتي، فأرشدوني سماحة الشيخ؟ كيف أتصرف جزاكم الله خيرًا؟","title":"نصيحة لشاب لا يستطيع الزواج","answer":"الجواب:  نوصيك بتقوى الله والصبر حتى تستطيع الزواج، ونوصيك أيضًا بالصوم إذا تيسر لك ذلك؛ لأن الله سبحانه يقول في كتابه العظيم: وَلْيَسْتَعْفِفِ الَّذِينَ لا يَجِدُونَ نِكَاحًا حَتَّى يُغْنِيَهُمُ اللَّهُ مِنْ فَضْلِهِ [النور:33]، فأنت مأمور بالاستعفاف عما حرم الله حتى يغنيك الله من فضله، وتستطيع الزواج. ونوصيك أيضًا بالصيام يقول النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء، فإذا كنت عاجزًا عن النكاح فاتق الله واصبر، واجتهد في البعد عن أسباب الفتنة، وعن النظر إلى النساء، أو مخالطة النساء حتى يسهل الله لك الزواج، وإن تيسر لك القرض من بعض إخوانك، وأن تتزوج فسوف يوفي الله عنك، اقترض من بعض إخوانك وتزوج وأبشر بالخير، الله يقول سبحانه: وَأَنكِحُوا الأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32]. ويقول النبي ﷺ: ثلاثة حق على الله عونهم ذكر منهم: المتزوج يريد العفاف ويقول ﷺ: من أخذ أموال الناس يريد أداءها أدى الله عنه. فأنت إذا أخذت ذلك تريد العفاف فأنت على خير، والله -جل وعلا- يوفي عنك  فإذا تيسر لك من إخوانك الطيبين من يقرضك، من يعينك على الزواج، ولو من جماعة، هذا منه كذا، وهذا منه كذا، حتى تتزوج فهذا مناسب، وينبغي البدار به، حرصًا على العفة والسلامة.  أما إذا لم يتيسر ذلك فاصبر وصابر، واجتهد في جمع ما تيسر من النقود حتى تستطيع الزواج، يسر الله أمرك، وأعانك على ما فيه عفتك وسلامتك. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9180/نصيحة-لشاب-لا-يستطيع-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_365/36514.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات"]},{"id":11005,"question":"رسالة جاءت من الموصل في العراق، وباعثها أحد الإخوة من هناك يقول: إنني المسلم (ن. ش. ح) يقول: إني شاب في السابعة والعشرين من عمري أريد أن أتزوج، ولا أطيق ذلك؛ لأننا في بلدنا يطلبون علينا المهر وهو خمسة إلى عشرة آلاف دينار، وأنا لا أملك سوى راتبي الذي لا يكفي إلا لعيشي أنا وعائلتي، فأرشدوني سماحة الشيخ؟ كيف أتصرف جزاكم الله خيرًا؟","title":"نصيحة لشاب لا يستطيع الزواج","answer":"الجواب:  نوصيك بتقوى الله والصبر حتى تستطيع الزواج، ونوصيك أيضًا بالصوم إذا تيسر لك ذلك؛ لأن الله سبحانه يقول في كتابه العظيم: وَلْيَسْتَعْفِفِ الَّذِينَ لا يَجِدُونَ نِكَاحًا حَتَّى يُغْنِيَهُمُ اللَّهُ مِنْ فَضْلِهِ [النور:33]، فأنت مأمور بالاستعفاف عما حرم الله حتى يغنيك الله من فضله، وتستطيع الزواج. ونوصيك أيضًا بالصيام يقول النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء، فإذا كنت عاجزًا عن النكاح فاتق الله واصبر، واجتهد في البعد عن أسباب الفتنة، وعن النظر إلى النساء، أو مخالطة النساء حتى يسهل الله لك الزواج، وإن تيسر لك القرض من بعض إخوانك، وأن تتزوج فسوف يوفي الله عنك، اقترض من بعض إخوانك وتزوج وأبشر بالخير، الله يقول سبحانه: وَأَنكِحُوا الأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32]. ويقول النبي ﷺ: ثلاثة حق على الله عونهم ذكر منهم: المتزوج يريد العفاف ويقول ﷺ: من أخذ أموال الناس يريد أداءها أدى الله عنه. فأنت إذا أخذت ذلك تريد العفاف فأنت على خير، والله -جل وعلا- يوفي عنك  فإذا تيسر لك من إخوانك الطيبين من يقرضك، من يعينك على الزواج، ولو من جماعة، هذا منه كذا، وهذا منه كذا، حتى تتزوج فهذا مناسب، وينبغي البدار به، حرصًا على العفة والسلامة.  أما إذا لم يتيسر ذلك فاصبر وصابر، واجتهد في جمع ما تيسر من النقود حتى تستطيع الزواج، يسر الله أمرك، وأعانك على ما فيه عفتك وسلامتك. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9180/نصيحة-لشاب-لا-يستطيع-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_365/36514.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات"]},{"id":11099,"question":"سماحة الشيخ! نعود إلى رسالة بعث بها المستمع أحمد فارع الجمهورية العربية اليمنية يقول: سماحة الشيخ! رجل قرر أن لا يتزوج لضيق ذات اليد أولًا، وثانيًا: للتفرغ في طلب العلم، مع العلم بأنه يخاف من الوقوع في المعصية، فهل في تركه للزواج إثم؟ وهل يجب عليه الزواج إذا استطاع؟ وجهوني جزاكم الله خيرًا.","title":"حكم ترك التزوج للتفرغ لطلب العلم مع خوف المعصية","answer":"الجواب:  الصواب أنه يجب عليه، إذا استطاع يجب عليه، ولاسيما إذا خاف على نفسه فلا إشكال في الوجوب؛ لقول النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج؛ وهذا أمر، والأمر للوجوب فإنه أغض للبصر وأحصن للفرج، فمن لم يستطع فعليه بالصوم فإنه له وجاء. فالمقصود أن الواجب عليه مع القدرة المبادرة بالزواج، وإذا كان يخشى صار الواجب آكد. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9277/حكم-ترك-التزوج-للتفرغ-لطلب-العلم-مع-خوف-المعصية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_290/29007.mp3","categories":["حكم الزواج وأهميته"]},{"id":11512,"question":"أخيرًا تسأل سماحتكم عن الطريقة الصحيحة للزواج؛ حتى يكون على الطريقة الإسلامية؟","title":"صفة الزواج الشرعي","answer":"الجواب:  الزواج الشرعي كون الرجل يخطب البنت المناسبة الدينة، ثم يجري العقد عليها بواسطة وليها، وهو أقرب عصبتها، وأقربهم الأب، ثم الابن، ثم ابن الابن، ثم الأخ عند عدم الأب، والجد، وعدم الأبناء، وهكذا. المقصود: أنه يتزوجها بواسطة وليها الذي هو أقرب عصبتها، ويكون بحضرة شاهدين عدلين، حال كونها سليمة، ليس فيها مانع، ليست في عدة، ولا محرمة، وليست كافرة، إلا أهل الكتاب المحصنات من اليهود والنصارى فيجوز نكاحهن للمسلم، إذا كن محصنات عفيفات، وتركهن أولى، والحرص على المسلمة أولى. هذا الزواج الشرعي، أن يكون باختيار المرأة الطيبة في دينها التي تناسبه، ومع ذلك يتولى تزويجها وليها، وهو أبوها، أو جدها، وعند عدمها؛ ابنها وابن ابنها، وعند عدمهم؛ الأخ الشقيق ثم الأخ لأب، هكذا بقية العصبة حسب الميراث الأقرب فالأقرب. ويكون ذلك بشاهدين عدلين برضاها لا بالإكراه، ولا بالجبر، بل برضاها، وبحضرة شاهدين عدلين، مع المهر المعتاد، نعم،  الذي ترضى به المرأة، نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9692/صفة-الزواج-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_384/38408.mp3","categories":["حكم الزواج وأهميته"]},{"id":12064,"question":"من دولة قطر رسالة بعث بها المستمع (ط. ع) أخونا يناقش قضية هامة ألا وهي: تأخير الشباب عن الزواج، فيقول: ما هو حكم الشرع في الشخص الذي يؤخر الزواج، مع العلم بأنه قادر على الزواج، لكنه يفكر دائمًا في صعوبات هذه الحياة، علمًا بأنه يبلغ من العمر الثالثة والثلاثين؟","title":"ظاهرة تأخر الشباب عن الزواج","answer":"الجواب:  الواجب على من قدر الزواج، هذا هو الصواب، مادام له شهوة يشتهي النكاح، فالواجب عليه المبادرة بالزواج إذا استطاع ذلك، لقول النبي ﷺ في الحديث الصحيح: يا معشر الشباب! من استطاع منكم الباءة؛ فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع؛ فعليه بالصوم؛ فإنه له وجاء هذا فيه الأمر (فليتزوج) والصواب أنه للوجوب إذا قدر عليه، وهو له شهوة، وإذا كان يخاف الزنا؛ صار الأمر أشد. فالحاصل: أنه يجب عليه إذا كانت له شهوة، وكان يستطيع النكاح، يجب عليه البدار، وعدم التأخير، وإذا كان يخشى الفتنة؛ وجب بكل حال أن يبادر بالزواج، حتى الشيخ الكبير إذا كانت عنده قدرة، وليس عنده ما يعفه؛ وجب عليه الزواج ولو كان شيخًا، يجب عليه الزواج؛ لأن العلة موجودة وهي خوف الفتنة. فالواجب على من عنده قدرة على الزواج، سواءً كان شيخًا، أو كهلًا، أو شابًا يجب عليه البدار بالزواج، وليس له التأخير، وإذا كان عنده واحدة لا تعفه، يعني: شهوته كبيرة، وليست الواحدة تعفه، وهو يستطيع نكاح الثانية؛ وجب عليه أن ينكح الثانية، وجب عليه أن ينكح الثانية والثالثة والرابعة إذا استطاع ذلك حتى يعف نفسه، وحتى يحصل به كثرة النسل والأمة، ولو لم ترض النساء، النساء من طبيعتهن أن لا يرضين بالضارات، لكن هو ينظر في الأصلح، ويسترضي زوجته بما يسر الله من المال وغيره، ويعدل، ولا يضر ذلك، لا بأس عليها أن ترضى بذلك، وعليه أن يعدل، وإذا أرضاهن جميعًا بما يسر الله من المال؛ فهذا خير إلى خير، والواجب عليهن أن يرضين، وأن يصبرن إذا عدل، ولم يحف، بل عدل واتقى الله. المقصود أن الواجب على الرجال من شباب وشيوخ أن يتزوجوا، وأن لا يؤخروا الزواج، إذا كانوا يشتهون النكاح، وعندهم قدرة؛ يجب البدار والمسارعة إلى الزواج؛ لقوله ﷺ: يا معشر الشباب! من استطاع منكم الباءة؛ فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج هو الذي لا تعفه الواحدة وهو على خطر يخشى الفتنة؛ يجب عليه أن يتزوج الثانية والثالثة إذا احتاج إليها والرابعة، إذا احتاج وقدر لا يتأخر، وعليه أن يعدل، ويتقي الله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، الواقع يا سماحة الشيخ! أن الشاب يواجه عددًا من المشاكل عندما يريد أن يتزوج، وأهم تلك المشاكل السكن، إذ لو سكن سكنًا جماعيًا مع أسرته، مع أمه وأبيه وإخوته قد يحدث شيء من المشاكل، بل إنه من المؤكد حدوثها، فما هو توجيه سماحتكم؟ الجواب: الله يقول: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] .. وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا [الطلاق:2]، إن استطاع أن ينفرد؛ انفرد، وإلا سكن مع أهله، واتقى الله ما استطاع حسب الطاقة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10249/ظاهرة-تاخر-الشباب-عن-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_434/43413.mp3","categories":["حكم الزواج وأهميته"]},{"id":12326,"question":"ننتقل إلى موضوع آخر يسأل عنه أخونا: صالح ناصر إسماعيل البلوشي يقول: أنا شاب في العشرين من عمري، وغير متزوج، لكني دائمًا أفكر في الزواج، وحالتي المادية لا تسمح لي بذلك في الوقت الحاضر، بماذا توصونني وتوجهونني؟ جزاكم الله خيرًا؟","title":"وصية لشاب تاقت نفسه للزواج وهو غير قادر عليه","answer":"الجواب:  نوصيك بما أوصى به النبي ﷺ الشباب، جاء في الحديث الصحيح، يقول النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة؛ فليتزوج الباءة: يعني: الزواج فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج ، ومن لم يستطع؛ فعليه بالصوم؛ فإنه له وجاء خرجه الشيخان في الصحيحين، من حديث عبد الله بن مسعود، رضي الله تعالى عنه. فإذا تيسر لك الاستدانة، أو القرض حتى تتزوج فافعل ذلك، وأبشر بالوفاء يوفي الله عنك، يقول النبي ﷺ: من أخذ أموال الناس يريد أداءها؛ أدى الله عنه فأنت تأخذها، تستلف، أو تشتري سلعة، وتبيعها سيارة، أو غيرها، تبيعها، ثم تتزوج، والله يوفي عنك، أبشر بالخير -إن شاء الله- فإن لم يتيسر هذا؛ فأكثر من الصوم، أكثر من الصوم حتى يسهل الله لك النكاح. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10516/وصية-لشاب-تاقت-نفسه-للزواج-وهو-غير-قادر-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_398/39804.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات"]},{"id":12385,"question":"مستمع يقول أحمد لطفي محمد يقول: أنا رجل أعزب، ولست متزوجًا، وأبلغ من العمر الثانية والثلاثين، هل أبدأ بالحج، أم بالزواج؟ جزاكم الله خيرًا.","title":"الأفضلية في تقديم الحج على الزواج والعكس","answer":"الجواب:  إذا كنت في حاجة للزواج، وتخشى على نفسك؛ فابدأ بالزواج، والحج بعدين، بعد الزواج تحج إذا استطعت، أما إذا كنت لا تخشى الفتنة، ولا تخشى على نفسك من تأخير الزواج؛ فابدأ بالحج، ثم تزوج بعد ذلك. المقصود: أنك تراعي ما هو الخطر، ما هو الذي يضرك وتخشى منه، فإن كان النكاح يضرك تأخيره، وتخشى على نفسك؛ فابدأ بالنكاح. وإن كنت لا تخشى شيئًا، وتخشى أن يفوت عليك الحج؛ فبادر بالحج، والحمد لله، اعمل بما هو أقل ضررًا، وأكثر نفعًا، وأنت أعلم بنفسك، أنت أعلم بنفسك، فإذا كنت في حاجة للزواج، وتخشى على نفسك من التأخير؛ فابدأ بالزواج، وإن كنت -بحمد الله- لا تخشى شيئًا، بل أنت مطمئن أنه لا شيء عليك، ولا يضرك التأخير؛ فابدأ بالحج، والحمد لله، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10586/الافضلية-في-تقديم-الحج-على-الزواج-والعكس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40105.mp3","categories":["حكم الحج والعمرة","حكم الزواج وأهميته"]},{"id":12434,"question":"يسأل عن الحكم في من يرغب في الحج، ولكنه لم يتزوج بعد؟","title":"حكم تقديم الحج على الزواج","answer":"الجواب:  إذا كان يستطيع أن يقدم الحج؛ قدم الحج، أما إذا كان لا، يخشى على نفسه وهو يشتهي الزواج، ويخشى من الفتنة فإنه يقدم الزواج، فإن استطاع الحج بعد ذلك حج، يقدم ما هو الأهم، فإذا كان يخشى على نفسه الفتنة؛ فإنه يقدم الزواج، ثم يحج بعد ذلك إذا استطاع، فإن كان لا، ما عنده خوف فتنة، والأمر في حقه ليس بشديد الحاجة إلى الزواج؛ فإنه يقدم الحج؛ لأن الله فرض عليه الحج مع الاستطاعة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10638/حكم-تقديم-الحج-على-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_403/40307.mp3","categories":["حكم الزواج وأهميته"]},{"id":12610,"question":"متى يكون الزواج واجبًا؟ ومتى يكون مندوبًا؟ ومتى يكون مباحًا؟","title":"الحال التي يكون فيها الزواج واجباً ومندوباً ومباحاً","answer":"الجواب:  يكون مندوبًا إذا اشتهى ذلك، ولا خطر عليه، فإذا كان عليه خطر؛ لأنه ذو شهوة، ويخشى على نفسه، فإنه يجب عليه النكاح؛ لقوله ﷺ: يا معشر الشباب! من استطاع منكم الباءة؛ فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج. فالواجب عليه يبادر حفاظًا على دينه، وعلى سمعته، وعلى عرضه، وقال بعض أهل العلم: يجب مطلقًا ما دام فيه شهوة، وما دام يستطيع، فإنه يلزمه، ولو لم يخف الفتنة؛ لعموم الحديث: يا معشر الشباب وهذا القول أقوى وأظهر، وإن من استطاع الزواج يلزمه الزواج ما دامت عنده شهوة، وما دام عنده قدرة، أما الإباحة فيباح لمن لا شهوة له، للخدمة، والإعانة على أمور الدنيا إذا أخبرها، وعرفت أنه ......... المقدم: لابد من الإخبار؟ الشيخ: يخبرها. نعم.  المقدم: نعم، نعم جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10832/الحال-التي-يكون-فيها-الزواج-واجبا-ومندوبا-ومباحا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41420.mp3","categories":["حكم الزواج وأهميته"]},{"id":12625,"question":"متى يكون الزواج واجبًا؟ ومتى يكون مندوبًا؟ ومتى يكون مباحًا؟","title":"الحال التي يكون فيها الزواج واجباً ومندوباً ومباحاً","answer":"الجواب:  يكون مندوبًا إذا اشتهى ذلك، ولا خطر عليه، فإذا كان عليه خطر؛ لأنه ذو شهوة، ويخشى على نفسه، فإنه يجب عليه النكاح؛ لقوله ﷺ: يا معشر الشباب! من استطاع منكم الباءة؛ فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج. فالواجب عليه يبادر حفاظًا على دينه، وعلى سمعته، وعلى عرضه، وقال بعض أهل العلم: يجب مطلقًا ما دام فيه شهوة، وما دام يستطيع، فإنه يلزمه، ولو لم يخف الفتنة؛ لعموم الحديث: يا معشر الشباب وهذا القول أقوى وأظهر، وإن من استطاع الزواج يلزمه الزواج ما دامت عنده شهوة، وما دام عنده قدرة، أما الإباحة فيباح لمن لا شهوة له، للخدمة، والإعانة على أمور الدنيا إذا أخبرها، وعرفت أنه ......... المقدم: لابد من الإخبار؟ الشيخ: يخبرها. نعم.  المقدم: نعم، نعم جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10832/الحال-التي-يكون-فيها-الزواج-واجبا-ومندوبا-ومباحا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_414/41420.mp3","categories":["حكم الزواج وأهميته"]},{"id":12657,"question":"المستمع محمد أحمد إسماعيل من جمهورية مصر العربية يقول: أنا أعزب، وأريد أن أحج بيت الله الحرام، هل يكون حجي صحيحًا قبل أن أتزوج؟","title":"حكم حج الإنسان قبل زواجه","answer":"الجواب:  نعم، لك أن تحج، بل يجب عليك أن تحج إذا كنت قادرًا، ولو لم تتزوج، الحج يجب مع الاستطاعة على الأعزب وغير الأعزب، من استطاع السبيل إليه؛ وجب عليه الحج، وإن كان لم يتزوج، ولكن يجب عليك البدار بالزواج إذا استطعت؛ لقول النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة؛ فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج فعليك أن تبادر قبل الحج من حين تستطيع، فإذا أخرت، ولم تبادر؛ وجب عليك الحج، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10867/حكم-حج-الانسان-قبل-زواجه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45809.mp3","categories":["حكم الحج والعمرة","حكم الزواج وأهميته"]},{"id":12661,"question":"أحد الإخوة المستمعين من العراق بغداد رمز إلى اسمه بـالمستنصر بالله، يقول: في مجتمعنا، وفي بعض المجتمعات الأخرى يعيبون على المرأة المتوفى عنها زوجها أن تتزوج بعده، فما حكم عملهم؟","title":"حكم من عاب على المرأة التزوج بعد وفاة زوجها","answer":"الجواب:  هذا غلط، ولا يجوز لهم أن يعيبوها، بل عليها أن تتزوج، وتجتهد في عفة نفسها، وغض بصرها، وتحصيل الذرية، وإنما يحرم هذا على أزواج النبي فقط -عليه الصلاة والسلام- حرم الله على أزواجه ﷺ أن ينكحن بعده. وأما غيرهن فلا حرج عليهن في ذلك، ولا تعاب في تزوجها بعد زوجها الذي مات، الذي يعيبها قد غلط وأخطأ عليها، بل ينبغي تشجيعها على الزواج؛ لما فيه من الخير العظيم، والمصالح الجمة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10871/حكم-من-عاب-على-المراة-التزوج-بعد-وفاة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_458/45813.mp3","categories":["قضايا المرأة","حكم الزواج وأهميته"]},{"id":12874,"question":"المستمع: أحمد حسوبة بعث يسأل ويقول: بلغت من العمر خمسة وأربعين عامًا، وذهبت إلى الحج، وقضيت المناسك كلها، هل لي حجة، أم لا؛ لأني لم أتزوج بعد؟","title":"حكم الحج لمن لم يتزوج","answer":"الجواب:  ليس الزواج من شرط الحج، الحج يصح من له زوجه، ومن ليس عنده زوجة، حجك إذا كنت أديت حقه، حجك صحيح، ولو كنت ما تزوجت، فالنكاح ليس بشرط في الحج، وليس الحج شرطًا في النكاح، كل منهما ليس شرطًا في الآخر، يحج قبل الزواج، وبعد الزواج، ويتزوج قبل الحج، أو بعد الحج، كل هذا -والحمد لله- أمره واسع. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11089/حكم-الحج-لمن-لم-يتزوج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_466/46606.mp3","categories":["حكم الحج والعمرة","حكم الزواج وأهميته"]},{"id":13219,"question":"يقول: الأفضل للشاب المسلم البحث عن زوجة صالحة كما قال الرسول ﷺ: خير متاع الدنيا الزوجة الصالحة فإن لم يجد، ووجد زوجة قد يؤثر عليها، فهل يتزوجها، وجزاكم الله خيرًا سماحة الشيخ؟","title":"الحث على الزواج بالمرأة الصالحة","answer":"الجواب:  إذا تيسرت الزوجة الصالحة؛ فليحرص؛ لقوله ﷺ: تنكح المرأة لأربع: لمالها، ولحسبها، ولجمالها، ولدينها؛ فاظفر بذات الدين تربت يداك وقوله ﷺ: وخير متاعها الزوجة الصالحة فليحرص على الزوجة الصالحة التي تحافظ على دين الله، وتحافظ على الصلاة، بعيدة عن تهمة الفواحش، بعيدة عن سائر المعاصي، يحرص لعله يجدها. فإن لم يجد؛ تزوج من تيسرت مادامت مسلمة عفيفة، يتزوجها ولو كان عندها نقص، ليست من الناس المعروفين بالمسابقة للأعمال الصالحات، وليست معروفة بالبعد عن شيء من المعاصي للضرورة: فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16] ما دامت مسلمة، فالحمد لله، لكن إذا تيسرت المرأة السليمة المعروفة بالاستقامة والصفات الحميدة؛ فليحرص عليها مهما أمكن. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11496/الحث-على-الزواج-بالمراة-الصالحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52008.mp3","categories":["حكم الزواج وأهميته"]},{"id":13230,"question":"الحقيقة أمامي رسالة كتبتها ابنتكم (ع. ع) كتبت هذه الرسالة بأسلوبها الخاص تقول: الحقيقة سماحة الشيخ! لا أدري من أين أبدأ رسالتي هذه لكم، فمجمل قصتي: بأنني فتاة جامعية على مشارف التخرج والحمد لله، وأنا الآن لم أتزوج، أعلم بأنك ستقول بأن الطريق ما زال أمامي، ولكن العادات في قريتنا هي السبب، حيث أن الآباء يزوجون البنات وهن في سن الخامسة عشرة، أما والدي فإنه يرفض جميع من يتقدم لخطبتي بحجة إكمال الدراسة الجامعية، فأصبحت الآن محط أنظار الناس باعتبار أنني من البنات اللاتي كبرن عن الزواج في نظر أهل القرية، وأنا -والحمد لله- لا أشكو من أي مشاكل عائلية، ولكنني أخشى من الزمن ولا أدري ماذا أعلم ماذا في علم الغيب، وتذكر هذه السائلة وتقول: كل ما أريده منكم -سماحة الشيخ- أن تقوم بنصح والدي؛ لأنني أعلم أن ذلك غير مجدي معه ولكن لعله يستجيب، وأطلب منكم الدعاء سماحة الشيخ، فأنا أعتبركم -جزاكم الله خيرًا- من الدعاة إلى الله، وجهوني في ضوء هذه الرسالة بالنصح والتوجيه لعل والدي يتغير ولعل حالي يتغير ما أنا فيه، فادعو لي -جزاكم الله خيرًا- وسلام الله عليكم ورحمته وبركاته، السائلة من الرياض (ع. ع)؟","title":"حث الآباء على تزويج بناتهم","answer":"الجواب:  نوصي جميع الرجال بأن يتقوا الله في بناتهم، وأن يحرصوا على تزويجهن بالأكفاء ولو لم يكملن الدراسة متى جاءكم يشاورها وإذا رضيت زوجها، سواءً كانت في المتوسطة أو في الثانوية أو في الدراسة الجامعية، لا يرد الكفء، ما دامت المرأة توافق فإنه يزوجها ولا يمنعها الزواج حتى تكمل الدراسة، فإنه قد يفوت الكفء وقد تكمل الدراسة ولا تجد الكفء بعد ذلك. فالواجب على الأولياء أن يتقوا الله وأن يزوجوا البنات متى جاء الكفء، متى خطبهن الكفء؛ لقوله ﷺ: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه إلا تفعلوه تكن فتنة في الأرض وفساد كبير وفي لفظ: فساد عريض. فالواجب على الولي متى جاء الكفء وخطب إليه أن يزوجه ولا ينظر إلى دراستها كملت، أو ما كملت ويشير عليها وينصحها بأن توافق حتى لو قالت: دعوني أكمل، لا، يقول لها: أنا أنصحك أن تقبلي، الرجل كفء ما هو على كل حال إننا نحصله متى أردناه، قد يذهب الكفء ولا يجيء كفء، فينصح لها حتى يزوجها ولو كانت في المتوسط أو في الثانوي إذا كانت أهلًا للزواج، سليمة قد عافاها الله يزوجها بنت خمسة عشر، أو أربعة عشر، أو ستة عشر لا بأس. فالمقصود: يختار لها الرجل الطيب، فإذا خطبها الكفء فالواجب عدم التفريط فيه، والواجب على البنت أن تقبل أيضًا، وعلى الأب والأخ والعم أن يوافق على ذلك، على كلهم أن يحرصوا .. على الأولياء أن يحرصوا وعلى البنات أن يقبلن إذا جاء الكفء ولا يضيعنه من أجل الدراسة، بل الكفء غنيمة؛ ولهذا قال ﷺ: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوه تكن فتنة في الأرض وفساد كبير، هذا توجيه النبي ﷺ. فعلى الآباء أن يتقوا الله، وعلى الأولياء جميعًا أن يتقوا الله وأن يزوجوا البنات متى خطبهن الأكفاء، ولو كن في الدراسة الثانوية أو المتوسطة، ولا يؤخروا تزويجهن لإكمال الدراسة الجامعية، فإن هذا فيه خطر، قد تكمل الدراسة ثم لا تجد الكفء، نسأل الله للجميع التوفيق والهداية، ونسأل الله للسائلة الزوج الصالح، نسأل الله أن ييسر لها الزوج الصالح وأن يوفق أباها لما فيه صلاحها وصلاح إخوتها، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا يا سماحة الشيخ على هذا التوجيه المبارك.","link":"https://binbaz.org.sa/fatwas/11515/حث-الاباء-على-تزويج-بناتهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_520/52016.mp3","categories":["حكم الزواج وأهميته"]},{"id":13916,"question":"السائلة التي رمزت لاسمها بـ (أ. أ. أ) تقول: فتاة تقول بأنها لا تريد الزواج مع أنها في الثانية والعشرين من العمر، وتريد أن تكمل تعليمها وأن تتفقه في دينها، وأن تتعلم العلم الشرعي، هل يجوز لها ذلك يا سماحة الشيخ؟","title":"حكم امتناع الفتاة عن الزواج بحجة طلب العلم","answer":"الجواب: السنة لها أن تتزوج؛ لأن ترك الزواج فيه خطر، والرسول يقول ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء وهذا يعم الرجال والنساء، كل مأمور؛ لما في ذلك من إحصان الفرج وغض البصر، وحصول الذرية التي تعبد الله، فالمؤمن يجتهد في طلب الزواج والمؤمنة كذلك إذا جاء الكفء، وعليها مع هذا أن تجتهد في أنواع الخير كالرجل، أما ترك الزواج فلا ينبغي، بل المشروع لها أن تجيب من خطب وأن يسعى وليها في تيسير الأزواج الطيبين إذا خطب لها وليها الزوج الصالح طيب.\nولكن لو صبرت حتى تكمل دراستها الجامعية فلا حرج في ذلك، إذا كان لا خشية عليها، إذا كان لا تخشى شرًا من جهة الشهوة لا تخشى الفتنة فلا بأس أن تكمل الدراسة، ولكن كونها تترك الزواج بالكلية هذا لا ينبغي أبدًا، بل السنة لها أن تجتهد في الزواج وإذا خطبها الكفء لا يرد، يقول النبي ﷺ: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوه تكن فتنة في الأرض وفساد كبير.\nولما تأيمت حفصة من زوجها لما مات زوجها -حفصة بنت عمر - عرضها عمر  على عثمان وعلى الصديق أبي بكر قال: إن شئت زوجتك حفصة .. ثم خطبها النبي ﷺ وتزوجها.\nفإذا سعى الولي لبنته أو أخته لدى الناس الطيبين فلا حرج، وإذا خطبها الكفء لا يرد، والرسول ﷺ نهى عن التبتل وهو ترك النكاح، والتبتل عبادة؛ لأن الإنسان على خطر إذا ترك، الزواج قد يبتلى بما حرم الله، نسأل الله السلامة. نعم.\nالمقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12312/حكم-امتناع-الفتاة-عن-الزواج-بحجة-طلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54404.mp3","categories":["حكم الزواج وأهميته","قضايا المرأة"]},{"id":13924,"question":"السائلة التي رمزت لاسمها بـ (أ. أ. أ) تقول: فتاة تقول بأنها لا تريد الزواج مع أنها في الثانية والعشرين من العمر، وتريد أن تكمل تعليمها وأن تتفقه في دينها، وأن تتعلم العلم الشرعي، هل يجوز لها ذلك يا سماحة الشيخ؟","title":"حكم امتناع الفتاة عن الزواج بحجة طلب العلم","answer":"الجواب: السنة لها أن تتزوج؛ لأن ترك الزواج فيه خطر، والرسول يقول ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء وهذا يعم الرجال والنساء، كل مأمور؛ لما في ذلك من إحصان الفرج وغض البصر، وحصول الذرية التي تعبد الله، فالمؤمن يجتهد في طلب الزواج والمؤمنة كذلك إذا جاء الكفء، وعليها مع هذا أن تجتهد في أنواع الخير كالرجل، أما ترك الزواج فلا ينبغي، بل المشروع لها أن تجيب من خطب وأن يسعى وليها في تيسير الأزواج الطيبين إذا خطب لها وليها الزوج الصالح طيب.\nولكن لو صبرت حتى تكمل دراستها الجامعية فلا حرج في ذلك، إذا كان لا خشية عليها، إذا كان لا تخشى شرًا من جهة الشهوة لا تخشى الفتنة فلا بأس أن تكمل الدراسة، ولكن كونها تترك الزواج بالكلية هذا لا ينبغي أبدًا، بل السنة لها أن تجتهد في الزواج وإذا خطبها الكفء لا يرد، يقول النبي ﷺ: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوه تكن فتنة في الأرض وفساد كبير.\nولما تأيمت حفصة من زوجها لما مات زوجها -حفصة بنت عمر - عرضها عمر  على عثمان وعلى الصديق أبي بكر قال: إن شئت زوجتك حفصة .. ثم خطبها النبي ﷺ وتزوجها.\nفإذا سعى الولي لبنته أو أخته لدى الناس الطيبين فلا حرج، وإذا خطبها الكفء لا يرد، والرسول ﷺ نهى عن التبتل وهو ترك النكاح، والتبتل عبادة؛ لأن الإنسان على خطر إذا ترك، الزواج قد يبتلى بما حرم الله، نسأل الله السلامة. نعم.\nالمقدم: جزاكم الله خيرًا يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12312/حكم-امتناع-الفتاة-عن-الزواج-بحجة-طلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_544/54404.mp3","categories":["حكم الزواج وأهميته","قضايا المرأة"]},{"id":13959,"question":"رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات تقول السائلة: أختكم في الله (ف. م) تسأل وتقول: ما حكم الشرع في فتاة ترفض الزواج وهي فتاة مسلمة ملتزمة صائنة لعفافها، ولذلك فهي ترى لا حاجة لها للزواج، بالإضافة إلى أنها تعيش في مجتمع يستهزئ بالدين ويسخر من الملتزمين به، لذلك فهي تحرص أن لا تكون أسرة في مثل هذا المجتمع خوفًا من الانحراف والضياع، التوجيه لو تكرمتم شيخ عبد العزيز.","title":"حكم امتناع المرأة عن الزواج ‏","answer":"الجواب: المشروع للمرأة وللرجل هو الزواج، هذا هو المشروع للشباب والفتيات هو الزواج؛ لما فيه من إحصان الفرج وغض البصر وتكثير النسل وتكثير الأمة، وقد قال الله  في كتابه العظيم: وَأَنكِحُوا الأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32]، وقال النبي عليه الصلاة والسلام: يا معشر الشباب! من استطاع منكم الباءة فليتزوج فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء، وكان ﷺ ينهى عن التبتل ويأمر بالزواج، ويقول: تزوجوا الولود الودود فإني مكاثر بكم الأمم يوم القيامة.\nفالمشروع للشاب وللفتاة المبادرة بالزواج والحرص على الزواج كما أرشد إليه النبي عليه الصلاة والسلام وأمر به، وللمصالح التي سبق ذكرها، والجلوس بدون زواج فيه خطر عظيم، فلا يليق بالشاب وهو قادر أن يتأخر عن الزواج، ولا يليق بالفتاة أن تتأخر عن الزواج إذا خطبها الشخص المناسب، لكن إذا كان لها عذر لا تحب أن تبديه للناس فهي أعلم بنفسها، والله المستعان. نعم.\nالمقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12372/حكم-امتناع-المراة-عن-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_604/60416.mp3","categories":["قضايا المرأة","نصائح وتوجيهات","حكم الزواج وأهميته"]},{"id":14193,"question":"هذا سائل للبرنامج يقول: سماحة الشيخ! أب رفض الزواج لابنته حتى بلغ عمرها أربعين سنة رغم خطبتها من شباب معروفين منذ ثمانية عشر سنة ولم يزوجها حتى بلغت ما يقارب من ثلاثة وأربعين سنة، بعد هذا العمر زوجها؟","title":"حكم تأخير الولي زواج موليته","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فهذا الأب الذي فعل هذا الفعل ظالم لبنته وعليه خطر من عقوبة الله له، إذا كان خطبها بعض الأكفاء ولم يزوجه لا يجوز للمسلم أن يعضل بنته ولا أخته ولا غيرهما من مولياته بل يجب أن يسارع إلى تزويجها إذا خطبها الكفء؛ لقول النبي ﷺ: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوه تكن فتنة في الأرض وفساد كبير ولأنها أمانة فالواجب عليه أداء الأمانة، هذه أمانة في ذمته يجب البدار إلى أداء الأمانة بتزويجها على من خطبها من الأكفاء والمسارعة في ذلك، ولأن تركها بدون تزويج من وسائل الشر ووسائل الفساد، ولأنه من الظلم. فالواجب على من فعل هذا التوبة إلى الله والحذر من العود إلى مثل ذلك مع غيرها، والواجب على الأولياء جميعًا أن يتقوا الله في مولياتهم وأن يزوجوهن متى جاء الكفء حتى ولو بالخطبة لهن، عمر  خطب لابنته حفصة، عرضها على الصديق وعرضها على عثمان ثم خطبها النبي ﷺ وتزوجها، فالولي يكون عنده النصح عنده المحبة لتزويج مولياته، لما في هذا من عفتهن وتيسير وجود من يكفلهن ولعل الله يرزقهن بعض الأولاد.\nفالحاصل أن حبس المرأة وعدم تزويجها مع وجود الأكفاء الخاطبين ظلم عظيم يستحق صاحبه العقوبة ويستحق التأديب من ولي الأمر، فوصيتي لجميع الأولياء أن يتقوا الله في مولياتهم وأن يبادروا ويسارعوا إلى تزويج المولية إذا خطبها الكفء سواء بنتًا أو أختًا أو بنت أخ أو بنت عم الواجب البدار بالتزويج إذا جاء الكفء وعدم التعطيل. نعم.\nالمقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/12646/حكم-تاخير-الولي-زواج-موليته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54801.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات"]},{"id":14486,"question":"المستمعة (ص. ص. ص) بعثت برسالة تقول فيها: هناك نظرة اجتماعية غريبة تجاه المرأة التي يتوفى زوجها فتتزوج من بعده، إذ تصبح حديث الناس، وينظر إليها على أنها امرأة غير وفية، إلى جانب نعتها بكثير من الصفات البذيئة، ويعير أولادها بها، بعكس النظرة إلى المرأة التي لا تتزوج، وبصرف النظر عما تفعله، نرجو التوجيه تجاه هذه المشكلة، جزاكم الله خيرًا.","title":"توجيه حول النظرة السيئة لمن تتزوج بعد وفاة زوجها","answer":"الجواب: تزوج المرأة بعد خروجها من العدة -عدة وفاة زوجها المتوفى- أمر مطلوب، والذين ينكرون عليها ذلك قد غلطوا غلطًا فاحشًا، وهكذا ذمهم لها، أو عيبهم لها، أو تنكيتهم في ذلك كل هذا غلط، بل ينبغي تشجيع النساء على الزواج؛ لأن الزواج فيه خير لهن؛ وذلك من أسباب غض البصر، وحفظ الفروج، ومن أسباب المزيد من الذرية، حتى ولو كانت كبيرة لا تنتج، فإن السنة لها الزواج إذا تيسر الزواج؛ لما فيه من الخير والتعاون على الخير، وغض البصر، وكف السمعة السيئة، والتعرض للأخطار، فالذين يلومون المرأة التي تتزوج بعد وفاة زوجها قد غلطوا وأعانوا على الباطل، فلا ينبغي الالتفات إليهم، ولا التعريج على قولهم، بل يجب عليهم أن يستغفروا الله، وأن يتوبوا مما فعلوا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12977/توجيه-حول-النظرة-السيىة-لمن-تتزوج-بعد-وفاة-زوجها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_625/62506.mp3","categories":["حكم الزواج وأهميته","قضايا المرأة"]},{"id":14575,"question":"الأخوات السائلات اللاتي رمزن لأسمائهن بـ (م. ن) يقلن في هذا سماحة الشيخ، نحن أخوات من أهالي المنطقة الشرقية، منا الموظفة، ومنا الأستاذة في الجامعة، ومنا الدارسة في الدراسات الجامعية المتقدمة، لنا أب -هداه الله- يرفض جميع من يتقدم لنا، مع العلم بأن المتقدمين منهم المؤهلين، ومنهم ذوي الأخلاق الحميدة، وذوي الالتزام بطاعة الله، وأبونا يرفض ذلك بحجج واهية ليس لها من الله سلطان، فهو يقول: بأنه لن يزوجنا إلا إذا كان المتقدم لنا من مدينتنا، مع أنه هداه الله متزوج من زوجتين من نفس المدينة، فالرجاء من سماحة الشيخ عبدالعزيز تقديم النصح لأبينا وإرشاده إلى الحق في برنامج نور على الدرب. جزاكم الله خيرًا.","title":"نصيحة لمن يمتنع عن زواج بناته","answer":"الجواب: بسم الله الرحمن الرحيم .\nالحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فالواجب على جميع الأولياء أن يتقوا الله في مولياتهم، وأن يزوجوهن إذا خطبهن الكفء، سواء كان الولي أبًا أو جدًا أو ولدًا أو أخًا أو عمًا أو غير ذلك.  الواجب على الولي أن يتقي الله، وأن يبادر بتزويج موليته، سواء كانت بنته أو أخته أو غير ذلك، ولا يجوز له التساهل في هذا أو التعلل بأشياء لا وجه لها؛ لقول النبي ﷺ: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوه تكن فتنة في الأرض، وفساد كبير ولقوله ﷺ: يا معشر الشباب، من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع فعليه بالصوم، فإنه له وجاء وهذا يعم الرجال والنساء، متى خطبت المرأة وجب تزويجها، إذا خطبها الكفء؛ لأن ذلك أحصن لفرجها، وأغض لبصرها، وأبعد لها عن الفتنة، سواء كانت مدرسة أو طالبة أو موظفة أو غير ذلك، وسواء كان في حاجة إلى مرتبها أم ليس له حاجة في ذلك. يجب على الأب وعلى غيره أن يتقي الله، وأن يراقب الله، وأن يحذر ظلم البنت في تأخير تزويجها، بل متى خطبها الكفء سواء كان من بلدها أو من قبيلتها أو من غير بلدها، أو من غير قبيلتها ما دام كفء في دينه، فالواجب تزويجه؛ لقوله ﷺ: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه، إلا تفعلوه تكن فتنة في الأرض، وفساد كبير ولم يقل: من أهلكم، من قبيلتكم، أو من بلدكم، لا، المهم صلاح أخلاقه ودينه. ولا يجوز حبس المرأة لأجل المرتب، أو لأجل خدمتها له، أو ما أشبه ذلك، بل يجب أن يزوجها، وأن يتقي الله فيها، ويطلب من يقوم بخدمته من سواها من خادم أو زوجة يتزوجها، أما أن يحبس بنته أو أخته من أجل أن تخدمه، أو من أجل أن يأخذ راتبها، هذا من الظلم، ويقول الرسول ﷺ: اتقوا الظلم، فإن الظلم ظلمات يوم القيامة نسأل الله للجميع الهداية. المقدم: اللهم آمين، جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/13072/نصيحة-لمن-يمتنع-عن-زواج-بناته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_557/55701.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات"]},{"id":14716,"question":"رسالة وصلت إلى البرنامج من المستمع أحمد حسوبة أيضًا من جمهورية مصر العربية، ويعمل في العراق، يقول: عمري الآن اثنان وأربعون سنة، ولم أتزوج، وسبق لي أن أديت فريضة الحج، لكني سمعت من بعض الناس يقولون: إن الزواج قبل الحج، ما رأيكم هل سقطت عن الفريضة أم لا؟","title":"هل تصح فريضة الحج لمن أداها قبل الزواج؟","answer":"الجواب: نعم، نعم، فالحج يكون قبل الزواج، وبعد الزواج لا حرج، إذا حج المسلم قبل الزواج، أو بعد الزواج بعد التكليف بعدما صار بالغًا سقطت عنه الفريضة، وإن كان لم يتزوج، نعم. لكن أوصيك بالجد في طلب الزواج؛ لأنك كبير السن الآن، فنوصيك -يا أخي- وننصحك أن تبادر بالزواج، وتحرص على الزواج؛ حرصًا على سلامة دينك، وعفة فرجك، وعلى تحصيل الذرية، فبادر -يا أخي- وسارع، ولو بالاستدانة والقرض إلى أن يعينك الله على التسديد. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13202/هل-تصح-فريضة-الحج-لمن-اداها-قبل-الزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_637/nour_63707.mp3","categories":["حكم الزواج وأهميته"]},{"id":14824,"question":"المستمعة (ن. م) من الكويت، تقول في رسالتها: أنا فتاة في بداية العشرينيات، وأنا وكأي فتاة تحلم بأن يمن الله عليها بزوج صالح، وذرية صالحة، ولكن المشكلة هنا أنني عندما أسمع بأن شخصًا قادمًا إلي أفرح كثيرًا، وأشكر الله، ولكني فجأة أرى نفسي حزينة، لا أريد الزواج، وكأن شيطانًا دخل إلى قلبي وأخافني، وأصبح قلقة بسبب وبغير سبب وحزينة، وأرفض هذا الشخص، ولكنني لا أعلم لماذا؟ سماحة الشيخ أنا -والحمد لله- أحب ختم المصحف، وأحب سماع القرآن الكريم كثيرًا، وأتوكل على الله في كل وقت، ولكن أشك أن هناك من عمل لي عملًا؛ لهذا الموضوع حتى لا أتزوج وحتى لا أفرح. أرجو توجيهي -جزاكم الله خيرًا- كيف أتصرف؟ وإن كنت أعلم أن النفع والضر بيد الله .","title":"توجيه لمن ترفض الزواج ولديها شكوك في سبب ذلك","answer":"الجواب: هذا من الشيطان، هذا يا ابنتي من الشيطان، فعليك أن تتعوذي بالله من الشيطان، وأن تعتمدي على الله ، وأن تحسني الظن به -جل وعلا-، فإذا خطبك من ترضين دينه وخلقه ومدح لك في دينه وأخلاقه بواسطة الثقات العارفين به، فاستعيني بالله وتزوجي، ودعي عنك هذه الوساوس وهذه الأفكار الرديئة فإنها من الشيطان، من عدو الله يثبطك بذلك، حتى تبقي في تعب ومشقة وحرمان من الزواج والذرية، والشيطان يحب كل شر للإنسان، ويدعوه إلى كل شر، هو يسره أن تبقي عانسة لا زوج لك، وربما عرضك بعد هذا لما حرم الله . فالواجب عليك تقوى الله، والمبادرة إلى الزواج إذا جاء الكفء وترك هذه الوساوس، وهذه الكراهة، وهذه البغضاء، وهذا التحرج، كل هذا من الشيطان عدو الله، ودعي عنك الوساوس، فإنه المأمون لك في هذا كله من الشيطان، لن يعمل لك شيئًا، ولكنه الشيطان يثبطك، ويسعى في منعك من الزواج؛ لأنه يحب أن كل إنسان لا يتزوج، وأن يبقى في الفساد والتعب والمشقة، نسأل الله السلامة، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/13331/توجيه-لمن-ترفض-الزواج-ولديها-شكوك-في-سبب-ذلك","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_643/nour_64312.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات","قضايا المرأة"]},{"id":15520,"question":"سماحة الشيخ بعض الأخوات الفتيات قد ترد الخطاب بحجة أنها ترغب في إكمال دراستها، أو أنها تريد شخصًا مكتملًا، هل لسماحتكم توجيه حول هذا؟","title":"توجيه لمن ترفض الزواج بحجة إكمال الدراسة","answer":"الجواب: المشروع للشاب والشابة المبادرة في الزواج، وأن لا يؤخر الزواج، فيشرع للرجل أن يبادر بالزواج، ويشرع للفتاة أن تبادر بالزواج إذا تيسر الكفء؛ لقول النبي ﷺ: يا معشر الشباب، من استطاع منكم الباءة فليتزوج، فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع فعليه بالصوم، فإنه له وجاء. والصواب: أنه واجب مع وجود الشهوة والاستطاعة، والمرأة كذلك إذا خطبها الكفء وجب عليها الموافقة، ولا يجوز لها التأخير إلى انتهاء الدراسة، أو لكذا وكذا؛ لأن في التأخير أخطارًا كثيرة، نعم.","link":"https://binbaz.org.sa/fatwas/14057/توجيه-لمن-ترفض-الزواج-بحجة-اكمال-الدراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56918.mp3","categories":["حكم الزواج وأهميته","نصائح وتوجيهات","قضايا المرأة"]},{"id":15699,"question":"هذا السائل من جمهورية مصر العربية -سماحة الشيخ- يقول: ما حكم نظر الشرع في نظركم يا سماحة الشيخ في الزواج المبكر؟ وما هو السن المناسب للزواج بالنسبة للفتاة والفتى؟","title":"حكم الزواج المبكر وبيان السن المناسب للزواج","answer":"الجواب: النبي ﷺ قال: يا معشر الشباب، من استطاع منكم الباءة فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع فعليه بالصوم؛ فإنه له وجاء فالتبكير بالزواج إذا تيسر أفضل والمبادرة؛ لأن الإنسان متى بلغ الحلم، عرضة للخطأ، فالمشروع له البدار إذا استطاع -البدار بالزواج- من حين يبلغ الحلم، إذا بلغ خمسة عشر سنة، فأكثر، وإن بلغ قبل ذلك، وأحس بحاجته للنساء، قبل الخمسة عشر إذا بلغ بإنزال المني؛ فلا بأس يتزوج. المقصود: أنه إذا بلغ ولو بغير الخمسة عشر، وهو يستطيع الزواج، يشرع له المبادرة.\nوهكذا البنت، إذا بلغت تسعًا فأكثر، إذا تيسر الزواج تزوج، بنت تسع، بنت عشر، بنت إحدى عشر؛ لا حرج، عائشة تزوجها النبي ﷺ وهي بنت سبع، ودخل بها وهي بنت تسع -رضي الله عنها-، نعم. المقدم: أحسن الله إليكم يا شيخ.","link":"https://binbaz.org.sa/fatwas/14257/حكم-الزواج-المبكر-وبيان-السن-المناسب-للزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_573/57308.mp3","categories":["حكم الزواج وأهميته"]},{"id":15924,"question":"السائل أبو إبراهيم من القصيم يقول: هل يجوز للأب أن يختار لابنته زوجًا صالحًا، ويخبره أو يحدثه بهذا الموضوع؟","title":"مشروعية التماس الزوج الصالح","answer":"الجواب: نعم، سن للأب يشرع له أن يلتمس لها الزوج الصالح، ويشير عليها به، كان عمر  لما تأيمت بنته حفصة عرضها على عثمان وعلى الصديق أبي بكر رجاء أن يتزوجها أحدهما، حتى تزوجها النبي ﷺ، فعرض المرأة على الرجل الصالح أمر مطلوب، كونه يحب لبنته الخير، أو لأخته، ويحرص لها على الزوج الصالح، فكل هذا مطلوب، ولو خطب لها الرجل الصالح، قال: يا فلان! أنا أعرض عليك بنتي أو أختي؛ لأنه يحبه في الله من أجل صلاحه، لا بأس، لكن لا يزوجها إلا برضاها. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14519/مشروعية-التماس-الزوج-الصالح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_577/57714.mp3","categories":["حكم الزواج وأهميته"]},{"id":16211,"question":"رسالة بتوقيع أحد الإخوة المستمعين يقول: ابنكم (د. هـ. ف) له قضية يقول فيها: أنا شاب ولي أمر عائلتي، وتقدم لأختي شاب خاطبًا لها، وبعد التأكد من استقامته؛ قبلت به بعد موافقة والدتي أيضًا، وتمت بعد ذلك الرؤيا بين أختي وذلكم الشاب -وبحمد الله- كل منهما موافق، ولكن بعد أيام فوجئت بتحول رأي الوالدة عن هذا الزواج؛ بحجة صغر سن هذه الأخت.يا سماحة الشيخ! إنه سبق وأن تقدم ثلاثة خطاب قبل هذا الشاب، وترفض الوالدة بحجة صغر سن البنت، علمًا بأن عمرها يقارب الرابعة والعشرين، وجهوني كيف أوفق بين وجوب تزويج هذه البنت، وبين رضا والدتي وتصرفاتها هذه، جزاكم الله خيرًا.","title":"التوفيق بين الزواج وطاعة الوالدة","answer":"الجواب: بنت أربعة وعشرين ليست صغيرة، بل كبيرة، قد تجاوزت وقت الزواج؛ فلا يجوز لوالدتك أن تمنع، ولا أن تحتج بهذه الحجة، وإذا كانت البنت راضية؛ فزوِّجها، ولو لم ترض أمك، يجب عليك أن تزوجها؛ لأن في ذلك عفتها، والسعي في سلامة عرضها، والجمع بينها وبين الخاطب المناسب، والحمد لله، والرسول يقول ﷺ: إنما الطاعة في المعروف لا طاعة لمخلوق في معصية الخالق والتأخر عن تزويجها مع وجود الكفء، ومع رغبتها؛ معصية. فالواجب عليك تنفيذ الزواج، والمشورة على والدتك بالكلام الطيب، أن تسمح، وأن ترضى؛ حتى يكون الأمر -إن شاء الله- عن رضا الجميع، فإن أبت، وأصرت؛ فطاعة الله مقدمة، إذا كانت البنت راضية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14878/التوفيق-بين-الزواج-وطاعة-الوالدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_751/nour_75106.mp3","categories":["حكم الزواج وأهميته","بر الوالدين"]},{"id":18139,"question":"شيخ عبد العزيز ! تقول الصحف: إن البيوت امتلأت بالعوانس. توجيهكم؟","title":"نصيحة في المبادرة بالزواج","answer":"الجواب: هذا ليس ببعيد، النساء كثير والشباب كثير لكن الزواج قليل لأسباب كثيرة، منها: أن البنت قد تقول: أصبر حتى أتخرج من الجامعة، والشاب قد يقول كذلك، قد يكون عنده فقر وعجز عن مئونة الزواج، قد يكون مبتلى بأشياء أخرى تمنعه من الزواج، فينبغي في مثل هذا التعاون والتكاتف على تسهيل الزواج. أولاً: بالنصيحة للشباب والفتيات بعدم التشدد. وثانيًا: بتسهيل المهور وعدم التكلف في المهور. ثالثًا: عدم التكلف في الولائم. والفتى ينبغي له أن يبادر بالزواج ولو ما عنده فلة، ولو ما ملك فلة، ولو أنه في طلب العلم يستعين بالله ويستأجر البيت ولا يتكلف ولو استدان بعض الدين، كل هذا ينبغي فيه التسهيل. وينبغي لوالدي البنت أن يعيناها وأن يسهلا حاجتها، وأن لا يتكلفا في طلب المهر ولا في مسألة الاحتفالات بالزواج والولائم، ينبغي في هذا الاختصار والتعاون في هذا الأمر حتى يتيسر الزواج لهذا وهذا للفتى وللفتاة، نسأل الله للجميع الهداية. نعم. المقدم: اللهم آمين، أي الأمرين يفضل الشيخ عبد العزيز مواصلة التعليم أو الزواج؟ الجواب: الذي أرى أن يبادر بالزواج ولا يمنعه مواصلة التعليم، يواصل التعليم ويتزوج، التعليم لا يمنع الزواج، ولو أنك تتعلم إذا تيسر الزواج يبادر بالزواج ويواصل التعليم، والمرأة ما له لزوم إن واصلت فالحمد لله، وإلا تقنع بما يسر الله وتمتثل قول زوجها، ولا تنتظر للشهادة الجامعية بل تتزوج؛ لأن هذا أحصن لفرجها، وأسلم لها، وأحصن لفرج الزوج، وأقرب إلى الوئام ووجود الذرية وصلاح المجتمع، فليس من شرط الزواج تمام التعليم الجامعي لا، حتى للرجل إذا تعلم الثانوي الحمد لله لكن في إمكان كل منهما أن يواصل بعد الزواج. نعم. المقدم: جزاكم الله خيرًا، شيخ عبد العزيز للمادة أثرها على حياة الناس عندما يتزوج الإنسان يريد أن يؤثث بيت، يريد أن يعيش حياة معينة، توجيهكم لو تكرمتم؟ الشيخ: هذا مما يعطل الزواج، ينبغي عدم التكلف ولو استأجر شقة، ولو استدان والله يوفي عنه  فينبغي لأهله أن يعينوه وأقاربه أن يعينوه، وينبغي له أن يحسن الظن بالله  ولا يشدد في الأمور، فينبغي له أن يبادر بالزواج ولو من طريق الاستدانة، ولو من طريق التسامح في الأثاث وفي شقة البيت أو فلة البيت، لا يتشدد في الأمور حتى يفرج الله الأمور. نعم. المقدم: يعني ليس من الضروري أن يعيش حياة الكمال مع بداية حياته الزوجية؟ الشيخ: ما ينبغي لا، ينبغي له أن يتساهل ويتسامح ولا ينبغي له أن يشدد في الأمور، ولكن بعد ذلك يغنيه الله، يسهل الله أمره وَمَنْ يَتَّقِ اللَّهَ يَجْعَلْ لَهُ مَخْرَجًا[الطلاق:2]. المقدم: استجاب الله لكم، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17174/نصيحة-في-المبادرة-بالزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_905/nour_90504.mp3","categories":["حكم الزواج وأهميته"]},{"id":18395,"question":"أخت لنا من الرياض بعثت برسالة تقول المرسلة (س. ر. أ) أختنا لها مجموعة من الأسئلة؛ في سؤالها الأول تقول:إنني طالبة في كلية الطب البشري وقد مضى على التحاقي بهذه الكلية أربع سنوات، وكانت مكللة بالنجاح بحمد الله، وأنا حريصة على مواصلة الدراسة ولذلك فإنني أحاول تجنب أي سبب يعوق سيري فيها وأصمم على ذلك، ثم إن أهم ما واجهني في ذلك كله هو رفضي للزواج لهذا السبب؛ لأن ذلك سيحتاج من وقتي الكثير، علمًا بأن الدراسة في هذه الكلية أهم عامل فيها هو الوقت الذي إن لم نستغله استغلالًا كاملًا فإن ذلك سيؤثر على التحصيل وعلى سير الدراسة، فهل يجوز لي أن أرفض الزواج أو أن أؤجله لهذا السبب؟ أم أنني آثمة في ذلك؟ أرجو الإفادة بالتوضيح جزاكم الله خيرًا.","title":"حكم تأخير المرأة للزواج لأجل الدراسة","answer":"الجواب: إذا كنت لا تخشين شرًا في إكمال الدراسة وأنت ليس عندك من الاندفاع إلى الزواج ما يسبب خطرًا عليك فلا حرج في الإكمال، أما إن كان هناك حاجة إلى الزواج خوفًا منك على نفسك في هذه المدة التي تقضينها في الدراسة، فالواجب عليك الزواج والبدار به حفاظًا على دينك وعفتك وسمعتك جميعًا، وقد قال النبي ﷺ في الحديث الصحيح: يا معشر الشباب! من استطاع منكم الباءة فليتزوج فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء. هذا الحديث العظيم يدل على شرعية المبادرة بالزواج، وهو يعم الشباب الذكور والإناث جميعًا، يعم الرجال والنساء، وقد ذهب بعض أهل العلم إلى وجوب ذلك مع الاستطاعة، وقال آخرون: إن خاف على نفسه أو خافت على نفسها وجب وإلا شرع فقط من دون وجوب. ومن تأمل حال الوقت وحال الناس اليوم يتضح له أن الواجب البدار بالزواج إذا تيسر، ولو تأخر في الدراسة أو تعطلت الدراسة، فحفظ دينك وعفتك وسمعتك مقدم على إكمال الدراسة، فعليك أن تتقي الله وأن تحرصي على سلامة دينك وسلامة عفتك وسمعتك من عدم ذلك، ولا تؤثري الدراسة على ما يسبب هذا الخطر، يسبب عليك خطرًا في دينك وعفتك، فعليك أن تتقي الله وأن تجتهدي في أسباب السلامة، فإن قويت على إكمال الدراسة من دون خطر فلا حرج إن شاء الله، وإلا فالواجب البدار بالزواج إذا تيسر والحرص عليه وإكمال الدراسة في بعد ذلك إن تيسر ذلك وإلا فلا حاجة إلى إكمال الدراسة. الزواج وعفة الفرج وعفة النظر وحصول الأولاد أولى من إكمال الدراسة، هذا ما ظهر لي في هذه المسألة، وإن كان في الدراسة اختلاط وجب عليك ترك هذه الدراسة والحذر من شرها والبدار بالزواج أو بالجلوس في البيت حتى يسهل الله الزواج، أو دراسة غير مختلطة.  أما الدراسة المختلطة مع الشباب في فصول الدراسة فشرها عظيم وعواقبها وخيمة والواجب عليك تركها والحذر من عواقبها الوخيمة، سواء كانت في الطب أو في غير الطب مطلقًا. ويكفي للمسلمة أن تتعلم ما يحفظ عليها دينها من كتاب الله وسنة رسوله عليه الصلاة والسلام وكفى والحمد لله، ولا تعرض دينها وعفتها وسمعتها للخطر، وليس تعلم الطب ولا غيره من الأمور الأخرى غير الدين بأمر ضروري بل هو فرض كفاية إذا قام به من يكفي سقط عن الباقين، وإذا كان تعلم هذا الطب أو غيره من الأمور الأخرى يفضي إلى المضرة الدينية والخطر العظيم على العفة فإنه لا يجوز حينئذ. فالمقصود أنه يكفيك أن تتعلمي من طريق الأسئلة ومن طريق حلقات العلم التي تسمعينها من بعيد غير مخالطة للرجال مع الاحتجاب والعفة والاحتشام فيما يحفظ عليك دينك ويبصرك في دينك، أو من طريق المذياع تسمعين من إذاعة القرآن في المملكة العربية السعودية من هذا النور نور على الدرب، من هذا البرنامج أو من غيره ما يعلمك دينك وما يحصل به لك البصيرة من دون حاجة إلى أن تتعلمي بواسطة الاختلاط ما فيه الخطر العظيم. نعم، الله المستعان. نعم. المقدم: الله المستعان! الموضوع واسع شيخ عبد العزيز ويحتاج إلى أن يناقش بعض الأمور، طالبات كلية الطب ... الشيخ: هذا واجب، واجب على البرنامج وعلى العلماء في كل مكان، العلماء في كل مكان وعلى العلماء في برنامج هذا نور على الدرب، واجب على الجميع أن يعلموا أبناءهم وبناتهم ما أوجب الله وما حرم الله، فإن أبناء المسلمين وبنات المسلمين أمانة في ذمة العلماء، والواجب على العلماء أينما كانوا في أي بلاد الله أن ينصحوا لله ولعباده، وأن يعلموا أبناء المسلمين وبنات المسلمين ما يجب عليهم، وأن يحذروهم مما يحرم عليهم، وأن يحذروهم من أسباب الخطر. والواجب على ولاة الأمور في كل دولة مسلمة أو منتسبة للإسلام الواجب عليها أن تتقي الله وأن تفصل الرجال عن النساء وأن تكون مدارس النساء منفصلة عن مدارس الرجال، وهكذا الكليات، يجب أن تكون كلية الرجال منفصلة عن كلية النساء في كل شيء في الشريعة.. في الفقه.. في الآداب.. في الهندسة.. في الطب.. في أي شيء، يجب أن تكون الدراسة منفصلة غير مختلطة، وأن يتحمل المسئولون النفقة في ذلك، وسوف يعينهم الله ويخلف عليهم ويؤيدهم وينصرهم إذا تحروا رضاه سبحانه واتباع شريعته، والحذر من أسباب الخطر على بلادهم وشعوبهم، هذا واجبهم جميعًا، هذا واجب على جميع المسئولين في أي دولة منتسبة للإسلام أن تتقي الله وأن تعمل على تعليم النساء وحدهن والرجال وحدهم حتى لا تقع الفتنة وحتى لا يقع ما لا تحمد عاقبته من الفتن والفساد، والله المستعان. نعم.","link":"https://binbaz.org.sa/fatwas/17485/حكم-تاخير-المراة-للزواج-لاجل-الدراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_863/nour_86304.mp3","categories":["حكم الزواج وأهميته"]},{"id":18399,"question":"يقول هذا السائل: يا سماحة الشيخ! هل يجوز لطالب العلم أن يؤجل الزواج ليتفرغ لطلب العلم؟","title":"حكم تأخير الزواج بسبب الاشتغال بطلب العلم","answer":"الجواب: نعم، له أن يؤجل الزواج ليتفرغ لطلب العلم ويجتهد في طلب العلم والتفقه في الدين، إذا كان لا يخشى فتنة، أما إن كان يخشى الفتنة فليبادر بالزواج. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/17465/حكم-تاخير-الزواج-بسبب-الاشتغال-بطلب-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91331.mp3","categories":["حكم الزواج وأهميته","العالم والمتعلم"]},{"id":18550,"question":"هل يجوز أن يعزف الشباب عن الزواج مع وجود القدرة على ذلك؟","title":"حكم العزوف عن الزواج مع القدرة عليه","answer":"الجواب: ........ الأمم بأمته عليه الصلاة والسلام.............. المهم هو حصول الرجل الصالح، والمهم في حق الرجل حصول المرأة الصالحة، كما قال النبي ﷺ: فاظفر بذات الدين تربت يداك قال -عليه الصلاة والسلام-: تنكح المرأة لأربع: لمالها ولحسبها ولجمالها ولدينها، فاظفر بذات الدين تربت يداك ويروى عنه -عليه الصلاة والسلام-...........\nكلما يغضب الله ، رزق الله الجميع التوفيق والهداية، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، إذًا ترك الزواج يعتبر حرام؟ الشيخ: لا يجوز، نعم، مع القدرة، نعم. المقدم: مع القدرة، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17657/حكم-العزوف-عن-الزواج-مع-القدرة-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_916/nour_91601.mp3","categories":["حكم الزواج وأهميته"]},{"id":18847,"question":"هذا أبو هيثم من ليبيا يقول: سماحة الشيخ، شخص بلغ الأربعين، ولم يتزوج حيث إنه ليس له رغبة في الزواج، وهو رجل يحب الخير، ويؤدي الفروض بأوقاتها، هل يأثم بتركه الزواج؟","title":"حكم الزواج على من لا رغبة له فيه","answer":"الجواب: إذا كان لا شهوة له لا يأثم، أما إذا كان له شهوة يلزمه الزواج إذا استطاع؛ لقول النبي ﷺ: يا معشر الشباب، من استطاع منكم الباءة فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج أما إن كان ما عنده شهوة، أو عاجزًا ما عنده قدرة؛ فلا حرج عليه. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17931/حكم-الزواج-على-من-لا-رغبة-له-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_791/nour_79116.mp3","categories":["حكم الزواج وأهميته"]},{"id":18849,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من دولة البحرين، المالكية، وباعثها مستمع من هناك يقول: محمد سلمان عبد الله، أخونا يقول في رسالته: سماحة الشيخ، إنني شاب وأريد الزواج من امرأة عقيم عاقر غير منجبة للأطفال؛ لأنني لا أريد الذرية والنسل، فهل هذا يجوز شرعًا، حتى ولو كنت ميسور الحال؟أفيدوني ووجهوني، جزاكم الله خيرًا.","title":"الزواج من امرأة عقيم لعدم الرغبة في الذرية","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فقد دلت سنة رسول الله -عليه الصلاة والسلام- أنه يشرع للمؤمن أن يلتمس الزوجة الودود الولود؛ لأن الرسول -عليه الصلاة والسلام- قال: تزوجوا الولود الودود، فإني مكاثر بكم الأمم يوم القيامة فالأفضل لك -يا أخي- أن تلتمس الولود الودود حتى تجمع بين المصلحتين، قضاء شهوتك وحاجتك وعفة نفسك، وتحصيل الأولاد التي تكثر بها الأمة، وينفعك الله بهم إذا صلحوا، هذا هو الأولى لك، والأفضل لك.  ونكاح العقيم لا شيء فيه لا بأس به، لا حرج في ذلك، لكن نكاح الولود الودود أفضل وأولى، وإذا جمعت بين المرأتين نكحت ودودًا ولودًا، ونكحت عقيمًا، وجمعت بين الأمرين؛ فلا بأس هذا إليك، ونسأل الله أن يوفق الجميع، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17977/الزواج-من-امراة-عقيم-لعدم-الرغبة-في-الذرية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_922/nour_92201.mp3","categories":["حكم الزواج وأهميته"]},{"id":19063,"question":"رسالة وصلت إلى البرنامج من دمشق وباعثها أحد الإخوة من هناك يقول: محمد قاسم رزق، أخونا له مجموعة من الأسئلة، في سؤاله الأول يسأل ويقول: أنا شاب عمري ثلاث وعشرون سنة، عندي مبلغ يكفيني للحج أو للزواج، فأرغب بالحج قبل أن أتزوج، فما رأيكم في الحج أبدأ به أم أبدأ بالزواج؟ جزاكم الله خيرًا.","title":"استحباب تقديم الزواج على الحج","answer":"الجواب: الذي أنصحك أن تبدأ بالزواج؛ لأن الخطر عظيم في العزوبة ولاسيما في هذا العصر؛ لكثرة الفتن وانتشار تبرج النساء، فأنصحك بأن تتزوج، ومتى تيسر الحج بعد ذلك تحج إن شاء الله. المقدم: بارك الله فيكم.. بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18276/استحباب-تقديم-الزواج-على-الحج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_884/nour_88401.mp3","categories":["حكم الزواج وأهميته"]},{"id":19151,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من إحدى الأخوات المستمعات من الأردن- عمان، تقول: أم محمد، أختنا كبعض المستمعين تسرد قصة مطولة لجزء من حياتها، وذيلت هذه القصة بأسئلة هي: هل أحاسب لأنني لم أتزوج طيلة هذه السنين؟ هل يعتبر إنفاقي على ولدي ثوابًا يغنيني عن إخراج زكاة أموالي؟ إنني أضيع صلاة الصبح أحيانًا بالنوم، فهل هذا إثم علي؟ الطبيب نصحني بأن لا أحج أبدًا رغم أني أشعر بالقدرة على ذلك....الشيخ: تعيدها واحد واحد؟المقدم: أبشر. هل أحاسب لأنني لم أتزوج طيلة هذه السنين؟","title":"حكم ترك المرأة للزواج","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد: فلا ريب أن الله سبحانه وتعالى شرع للرجال والنساء الزواج، وأمر به في كتابه العظيم؛ حيث قال سبحانه: وَأَنكِحُوا الأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللَّهُ مِنْ فَضْلِهِ [النور:32]، وقال النبي الكريم عليه الصلاة والسلام: يا معشر الشباب! من استطاع منكم الباءة فليتزوج فإنه أغض للبصر، وأحصن للفرج ، ومن لم يستطع فعليه بالصوم فإنه له وجاء. فأنت أيها الأخت في الله إذا كنت تستطيعين الزواج وقد خطبك من ترضينه، فأنت على خطر من الإثم؛ لأن الزواج فيه مصالح كثيرة، منها: أن ذلك من أسباب عفة الفرج، ومن أسباب غض البصر، ومن أسباب حسن السمعة، والبعد عن التهمة، ومن أسباب الأولاد الذين قد ينفعك الله بهم في هذه الدنيا وفي الآخرة بدعواتهم وصلاحهم وعملهم الصالح، ودعوتهم لك إلى غير ذلك. أما إن كنت لم يتيسر لك الزواج، وليس في طاقتك الزواج، بل ذلك إلى غيرك، فليس عليك شيء، الإنسان إنما يؤخذ بتفريطه وتساهله، أما إذا كنت ما خطبك أحد، أو خطبك من لا ترضين دينه ولا أمانته فليس عليك شيء. نعم. المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/18324/حكم-ترك-المراة-للزواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_886/nour_88601.mp3","categories":["حكم الزواج وأهميته"]},{"id":19303,"question":"رسالة وصلت إلى البرنامج باعثتها مستمعة تقول الطالبة هدى بن نايف بن عبد العزيز الثانوية العامة، أختنا تقول: أنا طالبة في الثانوية العامة أؤيد هذا البرنامج المشرق بالنور بالعلم والمعرفة، نشكر الله أولًا ثم نشكر أصحاب الفضيلة العلماء والقائمين على هذا البرنامج الساطع الطيب المفيد، أنا كما قلت طالبة في الثانوية العامة، متزوجة ولله الحمد وعمري ثمان عشرة سنة، وسعيدة جدًا مع زوجي، وفي عيشة طيبة.وأختي الكبيرة عمرها ثلاثون سنة ولم تتزوج إلى الآن؛ لأنها قدمت الدراسة على الزواج، فكبر سنها ولم يردها أحد؛ لأن عمرها تعدى الشباب، الشاب لا يريدها، وهي لا تريد الشيوخ أو الكبار في السن، وهي الآن نادمة على تفريطها في شبابها، وهي الآن تقف معي وتهمس في أذن كل طالبة في الكلية أو الجامعة أو الثانوية أو الكفاءة أو محو الأمية وتقول: لا تتركن الدراسة، ولكن تزوجن وأنتن تدرسن لكي لا تندمن إذا فات شبابكن أيها الفتيات الطيبات! وتجلسن في بيوت أهلكن بدون أزواج، إلى صديقاتي وزميلاتي وأخواتي في جميع مدارس الفتيات بالمملكة العربية السعودية أهدي إليكن سلامي وتحياتي، وأرفع هذه الرسالة إلى سماحة الوالد الشيخ عبد العزيز كي يرفدها بما يستطيع، جزاه الله خيرًا.","title":"حث الفتيات على عدم تأخير الزواج بسبب الدراسة","answer":"الجواب: نعم، أؤيد ما ذكرته البنت الطالبة، وأؤيد أيضًا ما ذكرته أختها، ولا شك أن الزواج أمر مطلوب، وينبغي للفتيات وينبغي أيضًا للشباب من الرجال المسارعة إليه، يقول النبي ﷺ: يا معشر الشباب! من استطاع منكم الباءة فليتزوج؛ فإنه أغض للبصر، وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء. والحمد لله أختك وإن كانت بلغت الثلاثين فهي لا تزال شابة، ولا تزال فتاة، وأسأل الله أن يسهل لها الزوج الصالح الطيب، وأن يثيبها على ما قصدت من طلب العلم وحرصت عليه من طلب العلم، وأبشرها أن الله سيسهل لها من الرجال الصالحين والشباب الطيبين ما يحصل به إن شاء الله الخير لها في دنياها وآخرتها. ولكني مع ذلك أنصح جميع الفتيات بأن يبادرن إلى الزواج، ولا يمنع ذلك وجودهن في الدراسة، فلا مانع من الجمع بين الدراسة وبين الزواج، ولو فرضنا أن الزوج لا يرغب أن تستمر في الدراسة فإنها تقطع الدراسة والحمد لله، يكفيها ما أخذت من العلم، وفي إمكانها المذاكرة والمطالعة في كتب العلم وتستفيد. أما تأخير الزواج إلى الانتهاء من الدراسة الجامعية؛ فهذا قد يسبب ترك الزواج وعدم الزواج، فأنا أنصح جميع الفتيات أن يبادرن بالزواج، وأن لا يؤخرن ذلك إلى النهاية من الدراسة الجامعية بل يبادرن، فإن تيسر لهن إكمال الدراسة مع الزوج فالحمد لله وإلا فالزواج مقدم ولو لم تكمل الدراسة، وفي إمكانها بعد ذلك أن تطالع وتستفيد وتذاكر، وربما حصل لها زوج صالح متخرج جامعي أو فوق الجامعي فيفيدها وينفعها أيضًا ويجبر بما حصل من النقص. فأكرر وأكرر أهيب بالفتيات بالمسارعة إلى الزواج، وهكذا الشباب من الرجال أهيب بالجميع المبادرة بالزواج، وأن لا يؤجلوا ذلك إلى نهاية الدراسة الجامعية فإن الإنسان لا يدري ماذا بقي من عمره ولا يدري ماذا يكون بعد ذلك، فالبدار البدار بالزواج هو المطلوب.  المقدم: جزاكم الله خيرًا، ونفع بكم.","link":"https://binbaz.org.sa/fatwas/18513/حث-الفتيات-على-عدم-تاخير-الزواج-بسبب-الدراسة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_894/nour_89410.mp3","categories":["حكم الزواج وأهميته"]},{"id":19467,"question":"أم أحمد من السودان تقول: هل تأثم المرأة إذا تركت الزواج خوفًا من أن يكون الزوج هو نارها، بمعنى: أنها تخاف ألا تقوم على حقه، وما توجيه سماحتكم؟","title":"حكم ترك المرأة الزواج خوفًا من شر الأزواج","answer":"الجواب: المشروع الزواج، المشروع للمرأة الزواج؛ لإحصان فرجها وتحصيل النسل، هذا هو المشروع، وقد يجب عليها إذا خافت على نفسها الزنا يجب، الرسول ﷺ قال: يا معشر الشباب! من استطاع منكم الباءة فليتزوج فإنه أغض للبصر وأحصن للفرج، ومن لم يستطع فعليه بالصوم فإنه له وجاء وهكذا المرأة فعليها أن تبادر إذا تيسر الكفء؛ لقوله ﷺ: إذا خطب إليكم من ترضون دينه وخلقه فزوجوه فعليها أن تبادر وتتزوج، وتحسن الظن بالله، وتبشر بالخير إن شاء الله، لا تسيء الظن بالله، تحسن الظن بالله وتقوم بالواجب وتجتهد والتوفيق بيد الله. أما ترك الزواج خوفًا من شر الزوج هذا غلط. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18713/حكم-ترك-المراة-الزواج-خوفا-من-شر-الازواج","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93907.mp3","categories":["حكم الزواج وأهميته"]}]
